# ELF / archive helpers (implemented here, no external nm/readelf needed) ---

def elf_symbols(data):
    """Return (defined_strong, undefined, sections) for an ELF64/32 object.
    defined_strong: set of global non-weak, non-common defined symbols.
    undefined: list of undefined global symbols in table order.
    sections: dict name->size (summed)."""
    defined, undefined, sections = set(), [], {}
    if len(data) < 16 or data[:4] != b'\x7fELF':
        return defined, undefined, sections
    is64 = data[4] == 2
    le = data[5] != 2
    en = '<' if le else '>'
    try:
        if is64:
            e_shoff = struct.unpack_from(en+'Q', data, 0x28)[0]
            e_shentsize, e_shnum, e_shstrndx = struct.unpack_from(en+'HHH', data, 0x3a)
        else:
            e_shoff = struct.unpack_from(en+'I', data, 0x20)[0]
            e_shentsize, e_shnum, e_shstrndx = struct.unpack_from(en+'HHH', data, 0x2e)
        secs = []
        for i in range(e_shnum):
            off = e_shoff + i*e_shentsize
            if is64:
                name, typ, flags, addr, offset, size, link, info, align, entsize = struct.unpack_from(en+'IIQQQQIIQQ', data, off)
            else:
                name, typ, flags, addr, offset, size, link, info, align, entsize = struct.unpack_from(en+'IIIIIIIIII', data, off)
            secs.append(dict(name=name, typ=typ, offset=offset, size=size, link=link, entsize=entsize))
        def getstr(tab_off, idx):
            if tab_off is None or idx == 0 and False: return ''
            end = data.find(b'\x00', tab_off+idx)
            if end < 0: return ''
            return data[tab_off+idx:end].decode('utf-8', 'surrogateescape')
        shstr = secs[e_shstrndx]['offset'] if 0 <= e_shstrndx < len(secs) else None
        for sec in secs:
            sec['sname'] = getstr(shstr, sec['name']) if shstr is not None else ''
            base = sec['sname']
            sections[base] = sections.get(base, 0) + sec['size']
        for sec in secs:
            if sec['typ'] not in (2, 11):  # SYMTAB, DYNSYM
                continue
            strsec = secs[sec['link']] if sec['link'] < len(secs) else None
            if strsec is None: continue
            entsize = sec['entsize'] or (24 if is64 else 16)
            if entsize == 0: continue
            for j in range(sec['size']//entsize):
                off = sec['offset'] + j*entsize
                if is64:
