            if sec['typ'] not in (2, 11):  # SYMTAB, DYNSYM
                continue
            strsec = secs[sec['link']] if sec['link'] < len(secs) else None
            if strsec is None: continue
            entsize = sec['entsize'] or (24 if is64 else 16)
            if entsize == 0: continue
