                if bind == 0: continue  # local
                if st_shndx == 0:  # UNDEF
                    if nm not in undefined: undefined.append(nm)
                elif st_shndx == 0xfff2:  # COMMON
                    pass
                elif bind == 2:  # weak defined
                    pass
                else:
                    defined.add(nm)
