        pass
    return defined, undefined, sections

def ar_members(data):
    """Yield (name, bytes) from a System V ar archive."""
    if not data.startswith(b'!<arch>\n'):
        return
    off = 8
    longnames = b''
    while off + 60 <= len(data):
        hdr = data[off:off+60]
        try:
            name = hdr[0:16].decode('utf-8','surrogateescape')
            size = int(hdr[48:58].decode('ascii','ignore').strip() or '0')
        except Exception:
            break
        body = data[off+60:off+60+size]
        nm = name.strip()
        if nm == '//':
            longnames = body
        elif nm == '/':
            pass
        elif nm.startswith('/') and nm[1:].strip().isdigit():
            idx = int(nm[1:].strip())
            end = longnames.find(b'\n', idx)
            real = longnames[idx:end if end>=0 else len(longnames)].decode('utf-8','surrogateescape').rstrip('/')
            yield real, body
        else:
            if nm.endswith('/'): nm = nm[:-1]
            yield nm, body
        off += 60 + size + (size & 1)

def file_defined_symbols(path):
    try:
        with open(path, 'rb') as f: data = f.read()
    except Exception:
        return set()
    if data.startswith(b'!<arch>\n'):
        s = set()
        for _nm, body in ar_members(data):
            d, _u, _sec = elf_symbols(body); s |= d
        return s
    d, _u, _sec = elf_symbols(data)
    return d

def object_sections_totals(paths):
    text = drw = dro = bss = 0
    for p in paths:
        try:
            with open(p,'rb') as f: data=f.read()
        except Exception:
            continue
        _d,_u,secs = elf_symbols(data)
        for name, size in secs.items():
            if name == '.text' or name.startswith('.text.'):
                text += size
            elif name == '.bss' or name.startswith('.bss.'):
                bss += size
            elif name.startswith('.data.rel.ro') or name.startswith('.rodata'):
                dro += size
            elif name == '.data' or name.startswith('.data.') or name.startswith('.sdata'):
                drw += size
    return text, drw, dro, bss

# --- tcc -ar tool ---
AR_USAGE = "usage: tcc -ar [crstvx] lib [files]\ncreate library ([abdiopN] not supported).\n"

def ar_error(msg):
    err_text(msg)
    raise TccExit(2)

def write_archive(libpath, members, verbose=False, create_msg=True):
    # members: list of (display_path, arcname, data)
    try:
        out = open(libpath, 'wb')
    except Exception:
        ar_error(f"tcc: ar: can't create file {libpath}\n" if libpath != '.' else "tcc: ar: can't create file .\n")
    # Build symbol index (GNU / member): big-endian count, offsets, strings
    sym_entries = []  # (sym, member_index)
    member_datas = []
    for disp, arc, data in members:
        d, _u, _s = elf_symbols(data)
        for sym in sorted(d):
            sym_entries.append((sym, len(member_datas)))
        member_datas.append((arc, data))
    # compute header sizes to get member offsets
    def hdr(name, size):
        # name field 16, mtime 12, uid 6, gid 6, mode 8, size 10, magic 2
        nm = name
        return (f"{nm:<16}"[:16] + f"{0:<12}" + f"{0:<6}" + f"{0:<6}" + f"{0o100644:<8o}" + f"{size:<10}" + "`\n").encode('utf-8','surrogateescape')
    # long names table if any arcname >15 or contains space
    longtab = b''
    arcnames = []
    for arc, data in member_datas:
        if len(arc) > 15 or ' ' in arc:
            arcnames.append('/'+str(len(longtab)))
            longtab += arc.encode('utf-8','surrogateescape') + b'/\n'
        else:
            arcnames.append(arc + '/')
    symtab_body = b''
    if sym_entries:
        strs = b''.join(s.encode('utf-8','surrogateescape')+b'\x00' for s,_ in sym_entries)
        symtab_body_len = 4 + 4*len(sym_entries) + len(strs)
    else:
        symtab_body_len = 0
    # offset layout: magic(8) [/ header 60+body+pad] [// if longtab] members
    base = 8
    if sym_entries:
        base += 60 + symtab_body_len + (symtab_body_len & 1)
    if longtab:
        base += 60 + len(longtab) + (len(longtab)&1)
    offsets = []
    cur = base
    for arc, data in member_datas:
        offsets.append(cur)
        cur += 60 + len(data) + (len(data)&1)
    try:
        out.write(b'!<arch>\n')
        if sym_entries:
            strs = b''.join(s.encode('utf-8','surrogateescape')+b'\x00' for s,_ in sym_entries)
            body = struct.pack('>I', len(sym_entries)) + b''.join(struct.pack('>I', offsets[i]) for _s,i in sym_entries) + strs
            # symbol table header mode field is 0 in reference output
            h = (f"{'/':<16}" + f"{0:<12}" + f"{0:<6}" + f"{0:<6}" + f"{0:<8}" + f"{len(body):<10}" + "`\n").encode()
            out.write(h); out.write(body)
            if len(body)&1: out.write(b'\n')
        if longtab:
            h = (f"{'//':<16}" + f"{0:<12}" + f"{0:<6}" + f"{0:<6}" + f"{0:<8}" + f"{len(longtab):<10}" + "`\n").encode()
            out.write(h); out.write(longtab)
            if len(longtab)&1: out.write(b'\n')
        for (arc, data), an in zip(member_datas, arcnames):
            out.write(hdr(an, len(data))); out.write(data)
            if len(data)&1: out.write(b'\n')
        out.close()
    except TccExit:
        raise
    except Exception:
        try: out.close()
        except Exception: pass
        ar_error(f"tcc: ar: can't create file {libpath} \n")

def do_ar(st, args):
    st.flush_version()
    # args: raw remaining tokens after -ar
    if len(args) == 0:
        err_text(AR_USAGE); raise TccExit(1)
    ops = ''
    idx = 0
    first = args[0]
    # Determine whether first is ops or archive name: it is an archive name
    # when it does not start with '-' and contains a dot.
    if (not first.startswith('-')) and ('.' in first):
        lib = first; idx = 1; ops = 'cr'
    else:
        ops = first[1:] if first.startswith('-') else first
        idx = 1
        if idx >= len(args):
            # single arg that looks like ops (or a name without dot) -> usage
            err_text(AR_USAGE); raise TccExit(1)
        lib = args[idx]; idx += 1
    files = []
    for tok in args[idx:]:
        if tok.startswith('-') and tok != '-':
            ops += tok[1:]
        else:
            files.append(tok)
    # validate unsupported letters
    for ch in ops:
        if ch in 'abdh iopN'.replace(' ',''):
            err_text(AR_USAGE); raise TccExit(1)
    mode_t = 't' in ops
    mode_x = 'x' in ops
    verbose = 'v' in ops
    if mode_t or mode_x:
        try:
            with open(lib,'rb') as f: data=f.read()
        except Exception:
            ar_error(f"tcc: ar: can't open file {lib}\n")
        members = list(ar_members(data))
        wanted = set(files) if files else None
        if mode_t:
            for nm,_body in members:
                if wanted is None or nm in wanted:
                    out_text(nm+'\n')
            return 0
        else:
            for nm, body in members:
                if wanted is None or nm in wanted or os.path.basename(nm) in wanted:
                    try:
                        with open(os.path.basename(nm),'wb') as o: o.write(body)
                    except Exception:
                        pass
            return 0
    # create / replace
    if lib == '':
        ar_error("tcc: ar: can't create file \n")
    if lib == '.':
        ar_error("tcc: ar: can't create file .\n")
    members = []
    for fn in files:
        try:
            with open(fn,'rb') as f: data=f.read()
        except Exception:
            # reference removes a partially named archive on member failure
            try:
                if os.path.exists(lib): os.remove(lib)
            except Exception: pass
            ar_error(f"tcc: ar: can't open file {fn} \n")
        if len(data) < 4 or data[:4] != b'\x7fELF':
            try:
                if os.path.exists(lib): os.remove(lib)
            except Exception: pass
            ar_error(f"tcc: ar: Unsupported Elf Class: {fn}\n")
        members.append((fn, os.path.basename(fn), data))
        if verbose:
            out_text(f"a - {fn}\n")
    # For 's' only (ranlib) with no files and existing lib, keep members
    if 's' in ops and not files and os.path.exists(lib):
        try:
            with open(lib,'rb') as f: old=f.read()
            old_members = [(nm,nm,body) for nm,body in ar_members(old)]
            write_archive(lib, old_members)
            return 0
        except TccExit:
            raise
        except Exception:
            pass
    # 'r' with an existing archive and files: replace/add members,
    # preserving other existing members.  Without 'c' this is the usual
    # ar behaviour; the reference behaves this way for r as well as cr
    # when the archive already exists?  It recreates for cr in our tests
    # when invoked as a fresh creation.  Keep simple: if 'r' in ops and
    # lib exists and 'c' not forcing truncation semantics differ little,
    # merge by basename.
    if 'r' in ops and files and os.path.exists(lib):
        try:
            with open(lib,'rb') as f: old=f.read()
            if old.startswith(b'!<arch>\n'):
                merged = {}
                order = []
                for nm, body in ar_members(old):
                    merged[nm]=(nm,nm,body); order.append(nm)
                for fn, arc, data in members:
                    if arc not in merged: order.append(arc)
                    merged[arc]=(fn,arc,data)
                members = [merged[k] for k in order]
        except Exception:
            pass
    write_archive(lib, members)
    return 0
