def decode_c_string(tok_text):
    # tok_text may have prefix; find first quote
    i = tok_text.find('"')
    if i < 0: return tok_text
    body = tok_text[i+1:]
    if body.endswith('"'): body=body[:-1]
    out=[]; j=0
    simple={'n':'\n','t':'\t','r':'\r','\\':'\\','"':'"',"'":"'",'a':'\a','b':'\b','f':'\f','v':'\v','0':'\0'}
    while j < len(body):
        c=body[j]
        if c=='\\' and j+1<len(body):
            n=body[j+1]
            if n=='x':
                k=j+2; h=''
                while k<len(body) and body[k] in '0123456789abcdefABCDEF': h+=body[k]; k+=1
                if h: out.append(chr(int(h,16)&0xff)); j=k; continue
            if n in '01234567':
                k=j+1; o=''
                while k<len(body) and k<j+4 and body[k] in '01234567': o+=body[k]; k+=1
                out.append(chr(int(o,8)&0xff)); j=k; continue
            out.append(simple.get(n,n)); j+=2; continue
        out.append(c); j+=1
    return ''.join(out)

def char_const_value(text):
    i=text.find("'")
    if i<0: return 0
    body=text[i+1:]
    if body.endswith("'"): body=body[:-1]
    if body=='' : return 0
    if body[0]!='\\':
        # multi-char: pack big-endian-ish (implementation-defined)
        v=0
        for ch in body: v=(v<<8)|ord(ch)
        return v
    # escape
    n=body[1] if len(body)>1 else ''
