def parse_pp_number(text):
    t=text.lower()
    # strip suffixes
    is_float = ('.' in t and not t.startswith('0x')) or ('e' in t and not t.startswith('0x')) or (t.startswith('0x') and 'p' in t)
    core=t
    while core and core[-1] in 'ulf':
        if core[-1]=='f': is_float=True
        core=core[:-1]
    if is_float:
        raise ValueError('float')
    unsigned = 'u' in t[len(core):] if len(t)>len(core) else False
    try:
        if core.startswith('0x'):
            v=int(core,16)
        elif core.startswith('0b'):
            v=int(core,2)
        elif len(core)>1 and core[0]=='0' and core[1:].isdigit():
            v=int(core,8)
        else:
            v=int(core,10)
    except Exception:
        raise ValueError('badnum')
    return v, unsigned

class Preprocessor:
    def __init__(self, st, writer=None, deps=None, collect_only=False, extra_include_dirs=None):
        self.st=st; self.writer=writer; self.deps=deps if deps is not None else []
        self.collect_only=collect_only
        self.extra_include_dirs=extra_include_dirs or []
        self.macros={}; self.dynamic_on=set(['__FILE__','__LINE__','__DATE__','__TIME__','__COUNTER__'])
        self.counter=0; self.once=set(); self.stack=[]
        self.test_wanted=1; self.test_counter=0; self.test_selected=False
        self._date=None; self._time=None

    # ---------- diagnostics ----------
    def diag(self, kind, msg, ppfile=None, line=None, category=None):
        st=self.st
        if kind=='warning' and st.warn_none:
            return
        is_err = (kind=='error') or st.warn_error or (category is not None and category in st.warn_error_specific)
        if self.writer is not None:
            self.writer.diagnostic_newline()
        st.flush_version()
        # include stack (all but current)
        cur = ppfile or (self.stack[-1] if self.stack else None)
        if self.stack:
            for f in self.stack:
                if f is cur: break
                err_text(f"In file included from {f.display}:{f.current_line}:\n")
        fname = cur.logical_name if cur else '-'
        ln = line if line is not None else (cur.current_line if cur else 1)
        err_text(f"{fname}:{ln}: {'error' if is_err else 'warning'}: {msg}\n")
        if is_err:
            raise PPError(msg)
    def error(self,msg,ppfile=None,line=None):
        self.diag('error',msg,ppfile,line)
    def warning(self,msg,ppfile=None,line=None,category=None):
        self.diag('warning',msg,ppfile,line,category)

    # ---------- token helpers ----------
    def canonical(self, toks):
        s=''
        for i,t in enumerate(toks):
            if i==0:
                s+=t.text
            else:
                s+=(' ' if t.space else '')+t.text
        return s
    def stringify(self, toks):
        parts=[]
        for i,t in enumerate(toks):
            if i>0 and t.space: parts.append(' ')
            parts.append(t.text)
        inner=''.join(parts)
        inner=inner.replace('\\','\\\\').replace('"','\\"')
        return '"'+inner+'"'

    # ---------- macro definition ----------
    def macro_from_def(self, name_tok, rest, ppfile, line):
        # rest: tokens after name on directive line
        name=name_tok.text
        macro=Macro(name)
        pos=0
        if pos < len(rest) and rest[pos].text=='(' and rest[pos].space=='' :
            # function-like
            pos+=1; params=[]; variadic=False; va_name='__VA_ARGS__'
            closed=False
            if pos < len(rest) and rest[pos].text==')':
                closed=True; pos+=1
            else:
                while pos < len(rest):
                    t=rest[pos]
                    if t.text=='...':
                        variadic=True; va_name='__VA_ARGS__'; pos+=1
                        if pos < len(rest) and rest[pos].text==')': closed=True; pos+=1; break
                        else: break
                    if t.kind!='ident':
                        break
                    pname=t.text; pos+=1
                    if pos < len(rest) and rest[pos].text=='...':
                        variadic=True; va_name=pname; pos+=1
                        if pos < len(rest) and rest[pos].text==')': closed=True; pos+=1; break
                        else: break
                    params.append(pname)
                    if pos < len(rest) and rest[pos].text==',':
                        pos+=1; continue
                    if pos < len(rest) and rest[pos].text==')':
                        closed=True; pos+=1; break
                    break
            if not closed:
                self.error('bad macro parameter list', ppfile, line)
            macro.params=params; macro.variadic=variadic; macro.va_name=va_name
            body=rest[pos:]
        else:
            body=rest
        macro.body=[t.copy() for t in body]
        if macro.body: macro.body[0].space=''
        return macro
    def macro_equal(self, a,b):
        if (a.params is None)!=(b.params is None): return False
        if a.params is not None:
            if len(a.params)!=len(b.params) or a.variadic!=b.variadic: return False
            amap={}; 
            for i,p in enumerate(a.params): amap[p]=i
            bmap={}
            for i,p in enumerate(b.params): bmap[p]=i
            ava = amap.get(a.va_name, a.va_name); bva=bmap.get(b.va_name,b.va_name)
            # compare bodies with params normalized
            def norm(toks, mp, va, vaname):
                out=[]
                for t in toks:
                    txt=t.text
                    if txt in mp: txt=f"\x01{mp[txt]}"
                    elif txt==vaname: txt='\x02'
                    out.append((txt, bool(t.space)))
                return out
            return norm(a.body,amap,ava,a.va_name)==norm(b.body,bmap,bva,b.va_name)
        return [(t.text,bool(t.space)) for t in a.body]==[(t.text,bool(t.space)) for t in b.body]
    def define_macro(self, macro, ppfile=None, line=None, echo=True, warn_redef=True):
        if macro.name in self.dynamic_on:
            self.dynamic_on.discard(macro.name)
        old=self.macros.get(macro.name)
        if warn_redef and old is not None and not self.macro_equal(old,macro):
            # echo still happens in reference? Redefined define is echoed in -dM before warning order unclear; echo after warning diag newline
            self.warning(f"{macro.name} redefined", ppfile, line)
        self.macros[macro.name]=macro
        if echo and self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(self.format_define(macro), line if (ppfile is not None and not getattr(ppfile,'is_cmdline',False)) else None)
    def format_define(self, macro):
        if macro.params is None:
            head=f"#define {macro.name}"
        else:
            ps=list(macro.params)
            if macro.variadic:
                if macro.va_name=='__VA_ARGS__' and '__VA_ARGS__' not in ps:
                    ps=ps+['__VA_ARGS__']
                # named va: name is not in params in our parse; reference prints it as plain param
                if macro.va_name!='__VA_ARGS__' and macro.va_name not in ps:
                    ps=ps+[macro.va_name]
            head=f"#define {macro.name}({','.join(ps)})"
        body=self.canonical(macro.body)
        return head+(' '+body if body else '')
    def undef_macro(self, name, ppfile=None, line=None, echo=True):
        if name in self.dynamic_on:
            self.dynamic_on.discard(name)
        self.macros.pop(name,None)
        if echo and self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(f"#undef {name}", line if (ppfile is not None and not getattr(ppfile,'is_cmdline',False)) else None)
    def define_simple(self, name, value_text, echo_text=None):
        # parse value_text into tokens using a dummy file
        dummy=PPFile('<command line>',None,'')
        lx=Lexer(value_text, dummy)
        toks=lx.tokenize()
        if toks: toks[0].space=''
        m=Macro(name, None, False, '__VA_ARGS__', toks)
        self.macros[name]=m
        if self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(echo_text if echo_text is not None else self.format_define(m))
    def define_func_text(self, decl, body_text):
        # decl like NAME(a,b)
        m=re.match(r'^([A-Za-z_$][A-Za-z0-9_$]*)\((.*)\)$', decl)
        name=m.group(1); params=[p.strip() for p in m.group(2).split(',')] if m.group(2).strip() else []
        dummy=PPFile('<command line>',None,'')
        toks=Lexer(body_text,dummy).tokenize()
        if toks: toks[0].space=''
        mo=Macro(name, params, False, '__VA_ARGS__', toks)
        self.macros[name]=mo
        if self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(self.format_define(mo))

    # ---------- macro expansion ----------
    def dynamic_value(self, tok):
        name=tok.text
        fname = tok.logical_file or (tok.file.logical_name if tok.file else '-')
        if name=='__FILE__':
            esc=fname.replace('\\','\\\\').replace('"','\\"')
