    except Exception:
        raise ValueError('badnum')
    return v, unsigned

class Preprocessor:
    def __init__(self, st, writer=None, deps=None, collect_only=False, extra_include_dirs=None):
        self.st=st; self.writer=writer; self.deps=deps if deps is not None else []
        self.collect_only=collect_only
        self.extra_include_dirs=extra_include_dirs or []
        self.macros={}; self.dynamic_on=set(['__FILE__','__LINE__','__DATE__','__TIME__','__COUNTER__'])
        self.counter=0; self.once=set(); self.stack=[]
        self.test_wanted=1; self.test_counter=0; self.test_selected=False
        self._date=None; self._time=None

    # ---------- diagnostics ----------
    def diag(self, kind, msg, ppfile=None, line=None, category=None):
        st=self.st
        if kind=='warning' and st.warn_none:
            return
        is_err = (kind=='error') or st.warn_error or (category is not None and category in st.warn_error_specific)
        if self.writer is not None:
            self.writer.diagnostic_newline()
        st.flush_version()
        # include stack (all but current)
        cur = ppfile or (self.stack[-1] if self.stack else None)
        if self.stack:
            for f in self.stack:
                if f is cur: break
                err_text(f"In file included from {f.display}:{f.current_line}:\n")
        fname = cur.logical_name if cur else '-'
        ln = line if line is not None else (cur.current_line if cur else 1)
        err_text(f"{fname}:{ln}: {'error' if is_err else 'warning'}: {msg}\n")
        if is_err:
            raise PPError(msg)
    def error(self,msg,ppfile=None,line=None):
        self.diag('error',msg,ppfile,line)
    def warning(self,msg,ppfile=None,line=None,category=None):
        self.diag('warning',msg,ppfile,line,category)

    # ---------- token helpers ----------
    def canonical(self, toks):
        s=''
        for i,t in enumerate(toks):
            if i==0:
                s+=t.text
            else:
                s+=(' ' if t.space else '')+t.text
        return s
    def stringify(self, toks):
        parts=[]
        for i,t in enumerate(toks):
            if i>0 and t.space: parts.append(' ')
            parts.append(t.text)
        inner=''.join(parts)
        inner=inner.replace('\\','\\\\').replace('"','\\"')
        return '"'+inner+'"'

    # ---------- macro definition ----------
    def macro_from_def(self, name_tok, rest, ppfile, line):
        # rest: tokens after name on directive line
        name=name_tok.text
        macro=Macro(name)
        pos=0
        if pos < len(rest) and rest[pos].text=='(' and rest[pos].space=='' :
            # function-like
            pos+=1; params=[]; variadic=False; va_name='__VA_ARGS__'
            closed=False
            if pos < len(rest) and rest[pos].text==')':
                closed=True; pos+=1
            else:
                while pos < len(rest):
                    t=rest[pos]
                    if t.text=='...':
                        variadic=True; va_name='__VA_ARGS__'; pos+=1
                        if pos < len(rest) and rest[pos].text==')': closed=True; pos+=1; break
                        else: break
                    if t.kind!='ident':
                        break
                    pname=t.text; pos+=1
                    if pos < len(rest) and rest[pos].text=='...':
                        variadic=True; va_name=pname; pos+=1
                        if pos < len(rest) and rest[pos].text==')': closed=True; pos+=1; break
                        else: break
                    params.append(pname)
                    if pos < len(rest) and rest[pos].text==',':
                        pos+=1; continue
                    if pos < len(rest) and rest[pos].text==')':
                        closed=True; pos+=1; break
                    break
            if not closed:
                self.error('bad macro parameter list', ppfile, line)
            macro.params=params; macro.variadic=variadic; macro.va_name=va_name
            body=rest[pos:]
        else:
            body=rest
        macro.body=[t.copy() for t in body]
        if macro.body: macro.body[0].space=''
        return macro
    def macro_equal(self, a,b):
        if (a.params is None)!=(b.params is None): return False
        if a.params is not None:
            if len(a.params)!=len(b.params) or a.variadic!=b.variadic: return False
            amap={}; 
            for i,p in enumerate(a.params): amap[p]=i
            bmap={}
            for i,p in enumerate(b.params): bmap[p]=i
            ava = amap.get(a.va_name, a.va_name); bva=bmap.get(b.va_name,b.va_name)
            # compare bodies with params normalized
            def norm(toks, mp, va, vaname):
                out=[]
                for t in toks:
                    txt=t.text
                    if txt in mp: txt=f"\x01{mp[txt]}"
                    elif txt==vaname: txt='\x02'
                    out.append((txt, bool(t.space)))
                return out
            return norm(a.body,amap,ava,a.va_name)==norm(b.body,bmap,bva,b.va_name)
        return [(t.text,bool(t.space)) for t in a.body]==[(t.text,bool(t.space)) for t in b.body]
    def define_macro(self, macro, ppfile=None, line=None, echo=True, warn_redef=True):
        if macro.name in self.dynamic_on:
            self.dynamic_on.discard(macro.name)
        old=self.macros.get(macro.name)
        if warn_redef and old is not None and not self.macro_equal(old,macro):
            # echo still happens in reference? Redefined define is echoed in -dM before warning order unclear; echo after warning diag newline
            self.warning(f"{macro.name} redefined", ppfile, line)
        self.macros[macro.name]=macro
        if echo and self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(self.format_define(macro), line if (ppfile is not None and not getattr(ppfile,'is_cmdline',False)) else None)
    def format_define(self, macro):
        if macro.params is None:
            head=f"#define {macro.name}"
        else:
            ps=list(macro.params)
            if macro.variadic:
                if macro.va_name=='__VA_ARGS__' and '__VA_ARGS__' not in ps:
                    ps=ps+['__VA_ARGS__']
                # named va: name is not in params in our parse; reference prints it as plain param
                if macro.va_name!='__VA_ARGS__' and macro.va_name not in ps:
                    ps=ps+[macro.va_name]
            head=f"#define {macro.name}({','.join(ps)})"
        body=self.canonical(macro.body)
        return head+(' '+body if body else '')
    def undef_macro(self, name, ppfile=None, line=None, echo=True):
        if name in self.dynamic_on:
            self.dynamic_on.discard(name)
        self.macros.pop(name,None)
        if echo and self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(f"#undef {name}", line if (ppfile is not None and not getattr(ppfile,'is_cmdline',False)) else None)
    def define_simple(self, name, value_text, echo_text=None):
        # parse value_text into tokens using a dummy file
        dummy=PPFile('<command line>',None,'')
        lx=Lexer(value_text, dummy)
        toks=lx.tokenize()
        if toks: toks[0].space=''
        m=Macro(name, None, False, '__VA_ARGS__', toks)
        self.macros[name]=m
        if self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(echo_text if echo_text is not None else self.format_define(m))
    def define_func_text(self, decl, body_text):
        # decl like NAME(a,b)
        m=re.match(r'^([A-Za-z_$][A-Za-z0-9_$]*)\((.*)\)$', decl)
        name=m.group(1); params=[p.strip() for p in m.group(2).split(',')] if m.group(2).strip() else []
        dummy=PPFile('<command line>',None,'')
        toks=Lexer(body_text,dummy).tokenize()
        if toks: toks[0].space=''
        mo=Macro(name, params, False, '__VA_ARGS__', toks)
        self.macros[name]=mo
        if self.st.d_mode!=0 and self.writer is not None:
            self.writer.write_echo(self.format_define(mo))

    # ---------- macro expansion ----------
    def dynamic_value(self, tok):
        name=tok.text
        fname = tok.logical_file or (tok.file.logical_name if tok.file else '-')
        if name=='__FILE__':
            esc=fname.replace('\\','\\\\').replace('"','\\"')
            return Tok(f'"{esc}"','string',tok.space,tok.line,tok.file,tok.at_bol,tok.disabled,logical_file=tok.logical_file)
        if name=='__LINE__':
            return Tok(str(tok.line),'number',tok.space,tok.line,tok.file,tok.at_bol,tok.disabled,logical_file=tok.logical_file)
        if name=='__DATE__':
            if self._date is None:
                now=datetime.datetime.now(); self._date=now.strftime('%b %e %Y')
            return Tok(f'"{self._date}"','string',tok.space,tok.line,tok.file,tok.at_bol,tok.disabled,logical_file=tok.logical_file)
        if name=='__TIME__':
            if self._time is None:
                now=datetime.datetime.now(); self._time=now.strftime('%H:%M:%S')
            return Tok(f'"{self._time}"','string',tok.space,tok.line,tok.file,tok.at_bol,tok.disabled,logical_file=tok.logical_file)
        if name=='__COUNTER__':
            v=Tok(str(self.counter),'number',tok.space,tok.line,tok.file,tok.at_bol,tok.disabled,logical_file=tok.logical_file); self.counter+=1; return v
        return tok

    def expand_tokens(self, toks):
        toks=[t.copy() for t in toks]
        i=0
        # record idents for bench
        for t in toks:
            if t.kind=='ident': self.st.pp_stats_idents.add(t.text)
        while i < len(toks):
            t=toks[i]
            if t.err:
                # flush is handled by caller grouping; raise here with location
                self.error(t.err, t.file, t.line)
            if t.kind!='ident':
                i+=1; continue
            name=t.text
            if name in self.macros and name not in t.disabled:
                macro=self.macros[name]
                if macro.params is None:
                    repl=[]
                    for j,bt in enumerate(macro.body):
                        nt=bt.copy(); nt.file=t.file; nt.line=t.line; nt.logical_file=t.logical_file
                        nt.at_bol = t.at_bol if j==0 else False
                        nt.disabled = t.disabled | {name}
                        nt.space = t.space if j==0 else (' ' if bt.space else '')
                        repl.append(nt)
                    if not repl and i+1 < len(toks):
                        toks[i+1].space = t.space + toks[i+1].space
                    toks[i:i+1]=repl
                    continue
                else:
                    # function-like: next token must be '('
                    if i+1>=len(toks) or toks[i+1].text!='(':
                        i+=1; continue
                    # parse args
                    args=[]; cur=[]; depth=0; j=i+1; closed=False; saw_comma=False
                    j+=1  # past (
                    if j < len(toks) and toks[j].text==')':
                        closed=True; j+=1; args=[]
                    else:
                        while j < len(toks):
                            tt=toks[j]
                            if tt.text=='(':
                                depth+=1; cur.append(tt)
                            elif tt.text==')':
                                if depth==0:
                                    closed=True; j+=1; break
                                depth-=1; cur.append(tt)
                            elif tt.text==',' and depth==0:
                                saw_comma=True; args.append(cur); cur=[]
                            else:
                                cur.append(tt)
                            j+=1
                        if closed: args.append(cur)
                    if not closed:
                        self.error('unterminated argument list invoking macro "'+name+'"', t.file, t.line)
                    named=len(macro.params)
                    # empty invocation F() -> args [] ; adjust
                    if not args and (named>0 or macro.variadic):
                        args=[[]]
                    # map params (duplicate params: last index wins) - build by position
                    # variadic handling
                    if not macro.variadic:
                        if len(args) < named:
                            self.error(f"macro '{name}' used with too few args", t.file, t.line)
                        if len(args) > named:
                            # a single empty arg for 0-param macro already handled (args==[])
                            self.error(f"macro '{name}' used with too many args", t.file, t.line)
                    else:
                        if len(args) < named:
                            self.error(f"macro '{name}' used with too few args", t.file, t.line)
                    param_to_arg={}
                    for pi,pname in enumerate(macro.params):
                        if pi < len(args): param_to_arg[pname]=args[pi]
                    va_toks=[]
                    if macro.variadic:
                        if macro.va_name=='__VA_ARGS__':
                            extra=args[named:]
                        else:
                            # named va includes arg at its own position index = named (params excludes va name)
                            extra=args[named:]
                            # also the named param itself maps to all args from position named onward, plus? GNU a... a is all variadic args
                        for k,a in enumerate(extra):
                            if k>0: va_toks.append(Tok(',','punct','',t.line,t.file,False,t.disabled,logical_file=t.logical_file))
                            va_toks.extend(x.copy() for x in a)
                        if macro.va_name!='__VA_ARGS__':
                            # va_name behaves as variadic args (a in F(x,a...) is args from a onward)
                            # Our params list excludes va name; args[named:] are those. But if invocation F(1,2,3), named=1 (x), extra=[2,3] correct.
                            param_to_arg[macro.va_name]=va_toks
                        param_to_arg['__VA_ARGS__']=va_toks
                    repl=self._substitute(macro, param_to_arg, t)
                    if not repl and j < len(toks):
                        toks[j].space = t.space + toks[j].space
                    toks[i:j]=repl
                    continue
            if name in self.dynamic_on and name not in self.macros:
                toks[i]=self.dynamic_value(t)
                i+=1; continue
            i+=1
        return toks

    def _substitute(self, macro, param_to_arg, inv_tok):
        body=macro.body
        # expanded-arg cache
        exp_cache={}
        def expanded(pname):
            if pname not in exp_cache:
                raw=param_to_arg.get(pname,[])
                exp_cache[pname]=self.expand_tokens(raw) if raw else []
            return exp_cache[pname]
        seq=[]  # tokens, may include '##' punct and placemarkers
        idx=0
        def push_arg(pname, use_expanded, space_hint):
            lst = expanded(pname) if use_expanded else param_to_arg.get(pname,[])
            if not lst:
                seq.append(Tok('','placemarker',space_hint,inv_tok.line,inv_tok.file,False,inv_tok.disabled,logical_file=inv_tok.logical_file))
                return
            for k,at in enumerate(lst):
                nt=at.copy(); nt.file=inv_tok.file; nt.line=inv_tok.line; nt.logical_file=inv_tok.logical_file
                nt.at_bol=False
                nt.space = space_hint if k==0 else (' ' if at.space else '')
                seq.append(nt)
        while idx < len(body):
            bt=body[idx]
            space_hint=' ' if bt.space else ''
            # stringify # param (but not ##)
            if bt.text=='#' and idx+1 < len(body) and body[idx+1].text in param_to_arg and not (idx>0 and body[idx-1].text=='##'):
                raw=param_to_arg[body[idx+1].text]
                seq.append(Tok(self.stringify(raw),'string',space_hint,inv_tok.line,inv_tok.file,False,inv_tok.disabled,logical_file=inv_tok.logical_file))
                idx+=2; continue
            if bt.text in param_to_arg:
                prev_paste = idx>0 and body[idx-1].text=='##'
                next_paste = idx+1 < len(body) and body[idx+1].text=='##'
                push_arg(bt.text, not (prev_paste or next_paste), space_hint)
                idx+=1; continue
            if bt.text=='##':
                seq.append(Tok('##','punct',space_hint,inv_tok.line,inv_tok.file,False,inv_tok.disabled,logical_file=inv_tok.logical_file)); idx+=1; continue
            nt=bt.copy(); nt.file=inv_tok.file; nt.line=inv_tok.line; nt.logical_file=inv_tok.logical_file; nt.at_bol=False
            nt.space=space_hint
            seq.append(nt); idx+=1
        # token pasting, with , ## __VA_ARGS__ GNU removal
        out=[]
        i=0
        while i < len(seq):
            if seq[i].text=='##':
                # pop left
                left = out.pop() if out else Tok('','placemarker','',inv_tok.line,inv_tok.file)
                right = seq[i+1] if i+1 < len(seq) else Tok('','placemarker','',inv_tok.line,inv_tok.file)
                # GNU: comma before ## with empty right placemarker removes comma (handled because left may be ',')
                if right.kind=='placemarker':
                    if left.text==',' and right.text=='':
                        # check whether this came from empty va: just drop comma when right empty and previous token in body was va
                        pass
                    elif left.kind!='placemarker':
                        out.append(left)
                    i+=2; continue
                if left.kind=='placemarker':
                    out.append(right); i+=2; continue
                merged_text=left.text+right.text
                # re-lex merged as a single token if possible
                dummy=PPFile('<macro>',None,'')
                mt=Lexer(merged_text,dummy).tokenize()
                if len(mt)==1:
                    nt=mt[0]; nt.file=inv_tok.file; nt.line=inv_tok.line; nt.logical_file=inv_tok.logical_file; nt.space=left.space; nt.disabled=left.disabled
                    out.append(nt)
                elif len(mt)>1:
                    for k,nt in enumerate(mt):
                        nt.file=inv_tok.file; nt.line=inv_tok.line; nt.logical_file=inv_tok.logical_file; nt.space=left.space if k==0 else ''
                        out.append(nt)
                i+=2; continue
            if seq[i].kind=='placemarker':
                # keep spacing info for following token
                if i+1 < len(seq) and seq[i].space:
                    seq[i+1].space = seq[i].space + seq[i+1].space
                i+=1; continue
            out.append(seq[i]); i+=1
        # mark disabled and first space/at_bol
        for k,nt in enumerate(out):
            nt.disabled = inv_tok.disabled | {macro.name}
            if k==0:
                nt.space=inv_tok.space; nt.at_bol=inv_tok.at_bol
        return out
