    # ---------- #if expression ----------
    def eval_defined(self, name_tok, ppfile):
        name=name_tok.text
        # -dt auto-define handling
        if self.st.dt and name.startswith('test_') and len(name)>5:
            self.test_counter += 1
            if self.test_counter == self.test_wanted:
                self.test_selected=True
                if self.writer is not None:
                    self.writer.write_test_marker(name, None)
                # define as empty macro
                self.macros[name]=Macro(name,None,False,'__VA_ARGS__',[])
                if name in self.dynamic_on: self.dynamic_on.discard(name)
        return 1 if (name in self.macros or name in self.dynamic_on) else 0

    def include_entries(self, quote, current_file):
        entries=[]  # (dir, is_system)
        if quote and current_file is not None:
            d=os.path.dirname(current_file.display)
            entries.append((d, current_file.is_system))
        for d in self.st.include_dirs: entries.append((d, False))
        for d in self.st.system_include_dirs: entries.append((d, True))
        for d in self.extra_include_dirs: entries.append((d, True))
        for d in env_paths('C_INCLUDE_PATH'): entries.append((d, True))
        if not self.st.nostdinc:
            for d in default_include_dirs(self.st): entries.append((d, True))
        return entries

    def find_include(self, filename, quote, current_file, is_next=False):
        if filename.startswith('/'):
            if os.path.isfile(filename) or os.path.isdir(filename):
                return (filename, filename, False, -1)
            return None
        entries=self.include_entries(quote, current_file)
        start=0
        if is_next and current_file is not None and current_file.found_index>=0:
            start=current_file.found_index+1
        for idx in range(start, len(entries)):
            d, isys = entries[idx]
            disp = filename if d=='' else d+'/'+filename
            if os.path.isfile(disp) or os.path.isdir(disp):
                return (disp, disp, isys, idx)
        return None

    def has_include_eval(self, toks, i, ppfile):
        # toks[i] is __has_include / __has_include_next ; expect ( ... )
        is_next = toks[i].text=='__has_include_next'
        j=i+1
        if j>=len(toks) or toks[j].text!='(':
            return None
        j+=1; start=j; depth=0
        while j < len(toks):
            if toks[j].text=='(' : depth+=1
            if toks[j].text==')':
                if depth==0: break
                depth-=1
            j+=1
        if j>=len(toks): return None
        inner=toks[start:j]
        val=0; quote=False; fname=None
        if inner and inner[0].kind=='string':
            fname=decode_c_string(inner[0].text); quote=True
        elif inner and inner[0].text=='<':
            parts=[]; ok=False
            for t in inner[1:]:
                if t.text=='>': ok=True; break
                parts.append(t.text)
            if ok: fname=''.join(parts)
        if fname is not None:
            val=1 if self.find_include(fname, quote, ppfile, is_next) else 0
        return (val, j+1)

    def process_if_tokens(self, toks, ppfile, line):
        toks=[t.copy() for t in toks]
        # repeatedly handle defined/has_include and macro expansion
        for _round in range(200):
            changed=False
            out=[]; i=0
            while i < len(toks):
                t=toks[i]
                if t.kind=='ident' and t.text=='defined':
                    if i+1 < len(toks) and toks[i+1].text=='(' and i+3 < len(toks) and toks[i+2].kind=='ident' and toks[i+3].text==')':
                        v=self.eval_defined(toks[i+2], ppfile)
                        out.append(Tok(str(v),'number',t.space,t.line,t.file,False,t.disabled,logical_file=t.logical_file)); i+=4; changed=True; continue
                    if i+1 < len(toks) and toks[i+1].kind=='ident':
                        v=self.eval_defined(toks[i+1], ppfile)
                        out.append(Tok(str(v),'number',t.space,t.line,t.file,False,t.disabled,logical_file=t.logical_file)); i+=2; changed=True; continue
                    out.append(t); i+=1; continue
                if t.kind=='ident' and t.text in ('__has_include','__has_include_next'):
                    r=self.has_include_eval(toks,i,ppfile)
                    if r is not None:
                        v,nxt=r; out.append(Tok(str(v),'number',t.space,t.line,t.file,False,t.disabled,logical_file=t.logical_file)); i=nxt; changed=True; continue
                out.append(t); i+=1
            toks=out
            # expand macros one pass (expand_tokens will expand all expandable)
            before=[(t.text,t.kind) for t in toks]
            expanded=self.expand_tokens(toks)
            after=[(t.text,t.kind) for t in expanded]
            toks=expanded
            if before!=after: changed=True
            # if any defined/has_include remain that we can handle, loop
            if any(t.text in ('defined','__has_include','__has_include_next') for t in toks):
                # next iteration will try; avoid infinite loop if malformed
                if not changed:
                    break
                continue
            if not changed:
                break
        return toks

    def eval_pp_expr(self, toks, ppfile, line, directive='#if'):
        if not toks:
            self.error('#if with no expression', ppfile, line)
        toks=self.process_if_tokens(toks, ppfile, line)
        # replace remaining identifiers with 0
        vals=[]
        for t in toks:
            if t.kind=='ident':
                vals.append(Tok('0','number',t.space,t.line,t.file,False,t.disabled,logical_file=t.logical_file))
            else:
                vals.append(t)
        canon = directive+' '+self.canonical(vals) if vals else directive
        # token stream for parser
        parser=ExprParser(vals, self, ppfile, line, canon)
        try:
            v=parser.parse()
        except BadExpr as e:
            if str(e)=='float':
                self.error('invalid constant in preprocessor expression', ppfile, line)
            self.error(f'bad preprocessor expression: {canon}', ppfile, line)
        return v

    # ---------- file processing ----------
    def read_ppfile(self, display, fs_path, is_system=False, found_index=-1):
        if display=='-':
            data=self.st.get_stdin()
            text=data.decode('utf-8','surrogateescape')
            pf=PPFile('-', None, text, False, len(data), -1)
            return pf
        try:
            if os.path.isdir(fs_path):
                return PPFile(display, fs_path, '', is_system, 0, found_index)
            with open(fs_path,'rb') as f: data=f.read()
        except Exception:
            return None
        return PPFile(display, fs_path, data.decode('utf-8','surrogateescape'), is_system, len(data), found_index)

    def add_dep(self, pf):
        # deps list entries are (display, is_system)
        for d,_s in self.deps:
            if d==pf.display: return
        self.deps.append((pf.display, pf.is_system))

    def do_include(self, filename, quote, is_next, parent_file, parent_line, directive_line_ended=True, from_cmdline=False):
        found=self.find_include(filename, quote, parent_file, is_next)
        if found is None:
            self.error(f"include file '{filename}' not found", parent_file, parent_line)
        disp, fs, isys, idx = found
        canon = os.path.realpath(fs) if fs else disp
        if canon in self.once:
            return
        if len(self.stack) >= 32:
            # reference reports at line 0 of the file it was trying to include
            # Build a temp file object for location
            tmp=PPFile(disp, fs, '', isys); tmp.current_line=0
            self.error('#include recursion too deep', tmp, 0)
        pf=self.read_ppfile(disp, fs, isys, idx)
        if pf is None:
            self.error(f"include file '{filename}' not found", parent_file, parent_line)
        self.add_dep(pf)
        self.st.pp_stats_bytes += pf.byte_len
        if pf.fs_path is not None:
            self.st.pp_stats_lines += pf.text.count('\n')
        if self.writer is not None and not from_cmdline:
            self.writer.before_include(parent_line, directive_line_ended)
            self.writer.marker(1, disp, 1)
        elif self.writer is not None and from_cmdline:
            self.writer.marker(1, disp, 1)
        self.process_file(pf, is_top=False)
        if self.writer is not None:
            self.writer.finish_line_if_needed()
            self.writer.marker(parent_line+1 if not from_cmdline else parent_line+1, parent_file.logical_name if parent_file else disp, 2)

    def check_extra(self, rest, ppfile, line):
        if rest:
            self.warning('extra tokens after directive', ppfile, line)

    def process_file(self, pf, is_top=False):
        self.stack.append(pf)
        try:
            toks=Lexer(pf.text, pf).tokenize()
            # assign logical location fields as we go
            logical_name=pf.display
            line_adjust=0  # logical = physical + adjust, adjusted at #line based on next token line
            pending_line_marker=None  # (line, name)
            conds=[]  # frames dict parent_active,current,taken,seen_else
            def cur_active():
                return conds[-1]['current'] if conds else True
            normal=[]
            normal_line=[None]
            def flush_normal():
                if normal:
                    expanded=self.expand_tokens(normal)
                    if expanded and self.writer is not None:
                        self.writer.write_group(expanded, normal_line[0])
                    normal.clear(); normal_line[0]=None
            i=0
            # group tokens into logical lines: a line starts with at_bol token
            # We'll iterate token by token accumulating lines.
            lines=[]
            cur=[]
            for t in toks:
                if t.at_bol and cur:
                    lines.append(cur); cur=[t]
                else:
                    cur.append(t)
            if cur: lines.append(cur)
            for line_toks in lines:
                if not line_toks: continue
                first=line_toks[0]
                phys_line=first.line
                log_line=phys_line+line_adjust
                pf.current_line=log_line
                pf.logical_name=logical_name
                # set token logical fields
                for t in line_toks:
                    t.line=t.line+line_adjust
                    t.logical_file=logical_name
                is_directive = first.text=='#'
                if is_directive:
                    flush_normal()
                    # directive tokens after '#'
                    dtoks=line_toks[1:]
                    # skip leading spaces are in token.space, tokens themselves present
                    if not dtoks:
                        continue
                    dname_tok=dtoks[0]
                    dname=dname_tok.text
                    rest=dtoks[1:]
                    active=cur_active()
                    # Conditional directives are always processed structurally
                    if dname in ('if','ifdef','ifndef'):
                        if not active:
                            conds.append(dict(parent=False,current=False,taken=False,seen_else=False))
                        else:
                            if dname=='if':
                                v=self.eval_pp_expr(rest, pf, log_line, '#if') if rest else self.error('#if with no expression',pf,log_line)
                                cond=bool(v)
                            else:
                                if not rest or rest[0].kind!='ident':
                                    self.error(f"invalid argument for '#{dname}'", pf, log_line)
                                nm=rest[0].text
                                isdef = nm in self.macros or nm in self.dynamic_on
                                cond=isdef if dname=='ifdef' else not isdef
                                if len(rest)>1: self.check_extra(rest[1:], pf, log_line)
                            conds.append(dict(parent=True,current=cond,taken=cond,seen_else=False))
                        continue
                    if dname=='elif':
                        if not conds: self.error('#elif without matching #if', pf, log_line)
                        fr=conds[-1]
                        if fr['seen_else']: self.error('#elif after #else', pf, log_line)
                        if not fr['parent'] or fr['taken']:
                            fr['current']=False
                        else:
                            v=self.eval_pp_expr(rest, pf, log_line, '#elif') if rest else self.error('#if with no expression',pf,log_line)
                            fr['current']=bool(v); fr['taken']=bool(v)
                        continue
                    if dname=='else':
                        if not conds: self.error('#else without matching #if', pf, log_line)
                        fr=conds[-1]
                        if fr['seen_else']: self.error('#else after #else', pf, log_line)
                        fr['seen_else']=True
                        if rest: self.check_extra(rest, pf, log_line)
                        fr['current']= fr['parent'] and not fr['taken']
                        if fr['current']: fr['taken']=True
                        continue
                    if dname=='endif':
                        if not conds: self.error('#endif without matching #if', pf, log_line)
                        if rest: self.check_extra(rest, pf, log_line)
                        conds.pop(); continue
                    if not active:
                        continue
                    # Non-conditional directives, only when active
                    if dname=='define':
                        if not rest:
                            self.error("invalid macro name '\\n'", pf, log_line)
                        name_tok=rest[0]
                        if name_tok.kind!='ident':
                            self.error(f"invalid macro name '{name_tok.text}'", pf, log_line)
                        macro=self.macro_from_def(name_tok, rest[1:], pf, log_line)
                        self.define_macro(macro, pf, log_line)
                        continue
                    if dname=='undef':
                        if not rest:
                            # reference consumes next line's first token in a buggy way; approximate with warning below in driver? Simple warning.
                            self.warning('extra tokens after directive', pf, log_line+1)
                            continue
                        # If name is not ident, reference silently ignores (observed #undef 1)
                        if rest[0].kind=='ident':
                            self.undef_macro(rest[0].text, pf, log_line)
                        if len(rest)>1: self.check_extra(rest[1:], pf, log_line)
                        continue
                    if dname in ('include','include_next'):
                        self.handle_include(rest, pf, log_line, dname=='include_next', phys_line)
                        continue
                    if dname=='error':
                        msg=self.canonical(rest)
                        self.error(f"#error {msg}" if msg else "#error", pf, log_line)
                    if dname=='warning':
                        msg=self.canonical(rest)
                        self.warning(f"#warning {msg}" if msg else "#warning", pf, log_line)
                        continue
                    if dname=='pragma':
                        if rest and rest[0].text=='once':
                            if len(rest)>1: self.check_extra(rest[1:], pf, log_line)
                            if pf.fs_path: self.once.add(os.path.realpath(pf.fs_path))
                            continue
                        # output pragma line: first token after pragma unexpanded, rest expanded
                        if self.writer is not None and self.st.d_mode!=2:
                            ptoks=[Tok('#','punct','',log_line,pf,True,logical_file=logical_name), Tok('pragma','ident','',log_line,pf,False,logical_file=logical_name)]
                            if rest:
                                firstp=rest[0].copy(); firstp.space=' '; ptoks.append(firstp)
                                if len(rest)>1:
                                    ptoks.extend(self.expand_tokens(rest[1:]))
                            self.writer.write_group(ptoks, log_line)
                        continue
                    if dname=='line' or dname_tok.kind=='number':
                        # #line N "f"  or  # N "f" flags
                        alltoks = dtoks if dname_tok.kind=='number' else rest
                        # macro expand alltoks
                        alltoks=self.expand_tokens(alltoks)
                        if not alltoks or alltoks[0].kind!='number' or not re.fullmatch(r'[0-9]+', alltoks[0].text):
                            self.error('wrong #line format', pf, log_line)
                        new_line=int(alltoks[0].text)
                        new_name=logical_name
                        extra_start=1
                        if len(alltoks)>1 and alltoks[1].kind=='string':
                            new_name=decode_c_string(alltoks[1].text); extra_start=2
                        if dname=='line':
                            if len(alltoks)>extra_start:
                                # warning location uses new name/line in reference
                                oldname=pf.logical_name; pf.logical_name=new_name
                                self.warning('extra tokens after directive', pf, new_line)
                                pf.logical_name=oldname
                        # adjust so next physical line maps to new_line
                        # next token physical line is phys_line+? use relationship at next line: adjust = new_line - (phys_line+1) in original physical terms.
                        # line_adjust currently applied; original phys of this directive:
                        orig_phys = phys_line - 0  # phys_line was before adjust? first.line before we added adjust: we saved phys_line=first.line before modification? first.line originally physical, yes because we set log after.
                        # Actually phys_line variable holds original physical (first.line before adding adjust)
                        line_adjust = new_line - (orig_phys+1)
                        logical_name=new_name
                        pf.logical_name=new_name
                        pending_line_marker=(new_line,new_name)
                        if self.writer is not None and self.st.d_mode!=2 and self.st.pp_style!=0:
                            # Emit marker now (reference emits it before next token; emitting now is equivalent unless EOF)
                            self.writer.finish_line_if_needed()
                            self.writer.marker(new_line, new_name)
                        continue
                    # unknown directive
                    disp = '#'+dname
                    self.warning(f'ignoring unknown preprocessing directive {disp}', pf, log_line)
                    continue
                else:
                    if not cur_active():
                        continue
                    # normal line: check lexer errors in order handled in expand
                    if pending_line_marker is not None:
                        pending_line_marker=None
                    # accumulate one line group and flush immediately (macro definitions between lines handled)
                    normal.extend(line_toks); normal_line[0]=log_line
                    flush_normal()
            flush_normal()
            if conds:
                # missing endif at last physical line
                last_line = pf.text.count('\n')+1 if pf.text and not pf.text.endswith('\n') else (pf.text.count('\n') if pf.text else 1)
                if pf.text.endswith('\n'): last_line=pf.text.count('\n')
                self.error('missing #endif', pf, last_line+line_adjust)
        finally:
            self.stack.pop()

    def handle_include(self, rest, pf, log_line, is_next, phys_line):
        if not rest:
            self.error("'#include' expects \"FILENAME\" or <FILENAME>", pf, log_line)
        toks=rest
        fname=None; quote=False; used=0
        def parse_header(tt):
            if tt and tt[0].kind=='string':
                return decode_c_string(tt[0].text), True, 1
            if tt and tt[0].text=='<':
                parts=[]
                for k in range(1,len(tt)):
                    if tt[k].text=='>':
                        return ''.join(parts), False, k+1
                    if tt[k].space and parts: parts.append(' ')
                    parts.append(tt[k].text)
                self.error('missing terminating > character', pf, log_line)
            return None
        r=parse_header(toks)
        if r is None:
            expanded=self.expand_tokens(toks)
            r=parse_header(expanded)
            if r is None:
                self.error("'#include' expects \"FILENAME\" or <FILENAME>", pf, log_line)
            fname,quote,used=r
            extra=expanded[used:]
        else:
            fname,quote,used=r
            extra=toks[used:]
        if extra:
            self.warning('extra tokens after directive', pf, log_line)
        # did the directive line end with a newline in source? approximate: if not last physical line without trailing newline, assume ended
        ended=True
        # Note: process_file groups lines; EOF include without newline handled approximately by writer (it pads)
        self.do_include(fname, quote, is_next, pf, log_line, ended)

    # ---------- top-level ----------
    def init_predefined(self, top_display):
        st=self.st
        # base
        for nm,val in PREDEFINED_BASE:
            self.define_simple(nm,val)
        if st.char_unsigned: self.define_simple('__CHAR_UNSIGNED__','1')
        if st.optimize: self.define_simple('__OPTIMIZE__','1')
        if st.pthread: self.define_simple('_REENTRANT','1')
        if st.leading_underscore: self.define_simple('__leading_underscore','1')
        for nm,val in PREDEFINED_REST:
            self.define_simple(nm,val)
            if nm=='__STDC_HOSTED__':
                self.define_simple('__STDC_VERSION__', '201112L' if st.std_is_c11 else '199901L')
        # after __WINT_TYPE__ (last in REST), reference -dD prints 8 blank lines
        if st.d_mode==1 and self.writer is not None and st.pp_style!=0:
            self.writer.write_raw('\n'*8)
        for nm,val in PREDEFINED_TAIL:
            self.define_simple(nm,val)
        for decl,body in PREDEFINED_FUNCS:
            self.define_func_text(decl,body)
        self.define_simple('__PRETTY_FUNCTION__','__FUNCTION__')
        self.define_func_text('__has_builtin(x)','0')
        self.define_func_text('__has_feature(x)','0')
        self.define_func_text('__has_attribute(x)','0')
        for nm in ('_Nonnull','_Nullable','_Nullable_result','_Null_unspecified'):
            self.define_simple(nm,'')
        # marker #163 in -dD
        if st.d_mode==1 and self.writer is not None and st.pp_style!=0:
            self.writer.marker(163,'<command line>')
        esc=top_display.replace('\\','\\\\').replace('"','\\"')
        self.define_simple('__BASE_FILE__', f'"{esc}"')

    def apply_cmdline_defines(self, top_pf):
        # pseudo cmdline file for diagnostics
        cmd=PPFile('<command line>',None,''); cmd.is_cmdline=True
        top_pf.current_line=0
        saved_stack=self.stack
        self.stack=[top_pf, cmd]
        line_no=164
        try:
            for kind, raw in self.st.cmd_defines:
                cmd.current_line=line_no; cmd.logical_name='<command line>'
                if kind=='D':
                    if '=' in raw:
                        namepart, val = raw.split('=',1)
                    else:
                        namepart, val = raw, '1'
                    if namepart=='':
                        line_no+=1; continue
                    # parse namepart as name or name(params)
                    dummy=PPFile('<command line>',None,'')
                    toks=Lexer(namepart+' '+val, dummy).tokenize()
                    if not toks or toks[0].kind!='ident':
                        bad = toks[0].text if toks else ''
                        # name may be a pp-number like 1X: lexer gives number
                        self.error(f"invalid macro name '{bad}'", cmd, line_no)
                    macro=self.macro_from_def(toks[0], toks[1:], cmd, line_no)
                    self.define_macro(macro, cmd, line_no)
                else:
                    self.undef_macro(raw, cmd, line_no)
                line_no+=1
        finally:
            self.stack=saved_stack
        return line_no

    def process_top(self, display, fs_path):
        # returns nothing; uses writer
        if self.st.dt and self.st.output_type=='prep':
            self.test_wanted=1
            first=True
            while True:
                self.test_counter=0; self.test_selected=False
                pf=self._make_top_pf(display, fs_path, reread=not first)
                if pf is None:
                    self.st.error(f"file '{display}' not found")
                self._process_top_once(pf)
                first=False
                if self.test_counter >= self.test_wanted:
                    self.test_wanted+=1
                    continue
                break
        else:
            pf=self._make_top_pf(display, fs_path)
            if pf is None:
                self.st.error(f"file '{display}' not found")
            self._process_top_once(pf)

    def _make_top_pf(self, display, fs_path, reread=False):
        if display=='-':
            if reread:
                return PPFile('-',None,'',False,0,-1)
            data=self.st.get_stdin()
            pf=PPFile('-',None,data.decode('utf-8','surrogateescape'),False,len(data),-1)
            self.st.pp_stats_bytes += len(data)
            return pf
        pf=self.read_ppfile(display, fs_path, False, -1)
        if pf is not None:
            self.st.pp_stats_bytes += pf.byte_len
            if pf.fs_path is not None:
                self.st.pp_stats_lines += pf.text.count('\n')
        return pf

    def _process_top_once(self, pf):
        self.macros={}; self.dynamic_on=set(['__FILE__','__LINE__','__DATE__','__TIME__','__COUNTER__']); self.counter=0
        if self.writer is not None:
            self.writer.begin_top(pf.display)
        self.add_dep(pf)
        self.init_predefined(pf.display)
        next_line=self.apply_cmdline_defines(pf)
        # -include files
        if self.st.include_files:
            cmd=PPFile('<command line>',None,''); cmd.is_cmdline=True
            cmd.logical_name='<command line>'
            saved_stack=self.stack; pf.current_line=0
            self.stack=[pf, cmd]
            try:
                ln=next_line
                for inc in self.st.include_files:
                    cmd.current_line=ln
                    if self.writer is not None and self.st.d_mode!=2 and self.st.pp_style!=0:
                        self.writer.marker(ln+1,'<command line>')
                    # The include directive is written in the context of the main file search for quotes:
                    # use a pseudo parent whose display dir matches top file for search, but diagnostics use cmdline.
                    # Temporarily set cmd.display for search dir resolution:
                    search_parent=PPFile(pf.display, pf.fs_path, '')
                    search_parent.logical_name='<command line>'; search_parent.current_line=ln
                    found=self.find_include(inc, True, search_parent, False)
                    if found is None:
                        self.error(f"include file '{inc}' not found", cmd, ln)
                    disp,fs,isys,idx=found
                    incpf=self.read_ppfile(disp,fs,isys,idx)
                    if incpf is None:
                        self.error(f"include file '{inc}' not found", cmd, ln)
                    self.add_dep(incpf)
                    self.st.pp_stats_bytes += incpf.byte_len
                    if incpf.fs_path is not None: self.st.pp_stats_lines += incpf.text.count('\n')
                    if self.writer is not None:
                        self.writer.marker(1,disp,1)
                    # process with stack = [pf, cmd, incpf handled by process_file]
                    self.process_file(incpf, is_top=False)
                    if self.writer is not None:
                        self.writer.finish_line_if_needed()
                        self.writer.marker(ln+1,'<command line>',2)
                    ln+=1
            finally:
                self.stack=saved_stack
        if self.writer is not None and self.st.d_mode!=2 and self.st.pp_style!=0:
            self.writer.marker(1, pf.display, 2)
        pf.current_line=1
        self.process_file(pf, is_top=True)
        if self.writer is not None:
            self.writer.end_top()

class BadExpr(Exception):
    pass

class ExprParser:
    def __init__(self, toks, pp, ppfile, line, canon):
        self.toks=toks; self.i=0; self.pp=pp; self.canon=canon
    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None
    def next(self):
        t=self.peek(); self.i+=1; return t
    def expect(self, txt):
        t=self.next()
        if t is None or t.text!=txt: raise BadExpr('bad')
    def parse(self):
        if not self.toks: raise BadExpr('bad')
        v=self.parse_ternary()
        if self.i!=len(self.toks): raise BadExpr('bad')
        return v
    def parse_ternary(self):
        v=self.parse_or()
        if self.peek() and self.peek().text=='?':
            self.next(); a=self.parse_ternary(); self.expect(':'); b=self.parse_ternary()
            return a if v else b
        return v
    def _binlevel(self, sub, ops):
        v=sub()
        while self.peek() and self.peek().text in ops:
            op=self.next().text
            # For logical operators we still parse RHS (constant folding, no side effects)
            r=sub()
            v=self.apply(op,v,r)
        return v
    def parse_or(self): return self._binlevel(self.parse_and, ('||',))
    def parse_and(self): return self._binlevel(self.parse_bitor, ('&&',))
    def parse_bitor(self): return self._binlevel(self.parse_bitxor, ('|',))
    def parse_bitxor(self): return self._binlevel(self.parse_bitand, ('^',))
    def parse_bitand(self): return self._binlevel(self.parse_eq, ('&',))
    def parse_eq(self): return self._binlevel(self.parse_rel, ('==','!='))
    def parse_rel(self): return self._binlevel(self.parse_shift, ('<','>','<=','>='))
    def parse_shift(self): return self._binlevel(self.parse_add, ('<<','>>'))
    def parse_add(self): return self._binlevel(self.parse_mul, ('+','-'))
    def parse_mul(self): return self._binlevel(self.parse_unary, ('*','/','%'))
    def apply(self,op,a,b):
        av=a[0]; bv=b[0]
        try:
            if op=='||': return (1 if (av or bv) else 0, False)
            if op=='&&': return (1 if (av and bv) else 0, False)
            if op=='|': return (av|bv, a[1] or b[1])
            if op=='^': return (av^bv, a[1] or b[1])
            if op=='&': return (av&bv, a[1] or b[1])
            if op=='==': return (1 if av==bv else 0, False)
            if op=='!=': return (1 if av!=bv else 0, False)
            if op=='<': return (1 if av<bv else 0, False)
            if op=='>': return (1 if av>bv else 0, False)
            if op=='<=': return (1 if av<=bv else 0, False)
            if op=='>=': return (1 if av>=bv else 0, False)
            if op=='<<': return (av<<bv, a[1])
            if op=='>>': return (av>>bv, a[1])
            if op=='+': return (av+bv, a[1] or b[1])
            if op=='-': return (av-bv, a[1] or b[1])
            if op=='*': return (av*bv, a[1] or b[1])
            if op=='/':
                if bv==0: raise BadExpr('bad')
                return (int(av/bv) if (av<0) != (bv<0) and av%bv!=0 else av//bv, a[1] or b[1])
            if op=='%':
                if bv==0: raise BadExpr('bad')
                return (av - int(av/bv)*bv if False else (abs(av)%abs(bv))*(1 if av>=0 else -1), a[1] or b[1])
        except BadExpr:
            raise
        except Exception:
            raise BadExpr('bad')
        raise BadExpr('bad')
    def parse_unary(self):
        t=self.peek()
        if t and t.text in ('+','-','!','~'):
            op=self.next().text; v=self.parse_unary()
            if op=='+': return v
            if op=='-': return (-v[0], v[1])
            if op=='!': return (0 if v[0] else 1, False)
            if op=='~': return (~v[0], v[1])
        return self.parse_primary()
    def parse_primary(self):
        t=self.next()
        if t is None: raise BadExpr('bad')
        if t.text=='(':
            v=self.parse_ternary(); self.expect(')'); return v
        if t.kind=='number':
            try:
                return parse_pp_number(t.text)
            except ValueError as e:
                raise BadExpr(str(e))
        if t.kind=='char':
            return (char_const_value(t.text), False)
        raise BadExpr('bad')
