        # Note: process_file groups lines; EOF include without newline handled approximately by writer (it pads)
        self.do_include(fname, quote, is_next, pf, log_line, ended)

    # ---------- top-level ----------
    def init_predefined(self, top_display):
        st=self.st
        # base
        for nm,val in PREDEFINED_BASE:
            self.define_simple(nm,val)
        if st.char_unsigned: self.define_simple('__CHAR_UNSIGNED__','1')
        if st.optimize: self.define_simple('__OPTIMIZE__','1')
        if st.pthread: self.define_simple('_REENTRANT','1')
        if st.leading_underscore: self.define_simple('__leading_underscore','1')
        for nm,val in PREDEFINED_REST:
            self.define_simple(nm,val)
            if nm=='__STDC_HOSTED__':
                self.define_simple('__STDC_VERSION__', '201112L' if st.std_is_c11 else '199901L')
        # after __WINT_TYPE__ (last in REST), reference -dD prints 8 blank lines
        if st.d_mode==1 and self.writer is not None and st.pp_style!=0:
            self.writer.write_raw('\n'*8)
        for nm,val in PREDEFINED_TAIL:
            self.define_simple(nm,val)
        for decl,body in PREDEFINED_FUNCS:
            self.define_func_text(decl,body)
        self.define_simple('__PRETTY_FUNCTION__','__FUNCTION__')
        self.define_func_text('__has_builtin(x)','0')
        self.define_func_text('__has_feature(x)','0')
        self.define_func_text('__has_attribute(x)','0')
        for nm in ('_Nonnull','_Nullable','_Nullable_result','_Null_unspecified'):
            self.define_simple(nm,'')
        # marker #163 in -dD
        if st.d_mode==1 and self.writer is not None and st.pp_style!=0:
            self.writer.marker(163,'<command line>')
        esc=top_display.replace('\\','\\\\').replace('"','\\"')
        self.define_simple('__BASE_FILE__', f'"{esc}"')

    def apply_cmdline_defines(self, top_pf):
        # pseudo cmdline file for diagnostics
        cmd=PPFile('<command line>',None,''); cmd.is_cmdline=True
        top_pf.current_line=0
        saved_stack=self.stack
        self.stack=[top_pf, cmd]
        line_no=164
        try:
            for kind, raw in self.st.cmd_defines:
                cmd.current_line=line_no; cmd.logical_name='<command line>'
                if kind=='D':
                    if '=' in raw:
                        namepart, val = raw.split('=',1)
                    else:
                        namepart, val = raw, '1'
                    if namepart=='':
                        line_no+=1; continue
                    # parse namepart as name or name(params)
                    dummy=PPFile('<command line>',None,'')
                    toks=Lexer(namepart+' '+val, dummy).tokenize()
                    if not toks or toks[0].kind!='ident':
                        bad = toks[0].text if toks else ''
                        # name may be a pp-number like 1X: lexer gives number
                        self.error(f"invalid macro name '{bad}'", cmd, line_no)
                    macro=self.macro_from_def(toks[0], toks[1:], cmd, line_no)
                    self.define_macro(macro, cmd, line_no)
                else:
                    self.undef_macro(raw, cmd, line_no)
                line_no+=1
        finally:
            self.stack=saved_stack
        return line_no

    def process_top(self, display, fs_path):
        # returns nothing; uses writer
        if self.st.dt and self.st.output_type=='prep':
            self.test_wanted=1
            first=True
            while True:
                self.test_counter=0; self.test_selected=False
                pf=self._make_top_pf(display, fs_path, reread=not first)
                if pf is None:
                    self.st.error(f"file '{display}' not found")
                self._process_top_once(pf)
                first=False
                if self.test_counter >= self.test_wanted:
                    self.test_wanted+=1
                    continue
                break
        else:
            pf=self._make_top_pf(display, fs_path)
            if pf is None:
                self.st.error(f"file '{display}' not found")
            self._process_top_once(pf)

    def _make_top_pf(self, display, fs_path, reread=False):
        if display=='-':
            if reread:
                return PPFile('-',None,'',False,0,-1)
            data=self.st.get_stdin()
            pf=PPFile('-',None,data.decode('utf-8','surrogateescape'),False,len(data),-1)
            self.st.pp_stats_bytes += len(data)
            return pf
        pf=self.read_ppfile(display, fs_path, False, -1)
        if pf is not None:
            self.st.pp_stats_bytes += pf.byte_len
            if pf.fs_path is not None:
                self.st.pp_stats_lines += pf.text.count('\n')
        return pf

    def _process_top_once(self, pf):
        self.macros={}; self.dynamic_on=set(['__FILE__','__LINE__','__DATE__','__TIME__','__COUNTER__']); self.counter=0
        if self.writer is not None:
            self.writer.begin_top(pf.display)
        self.add_dep(pf)
        self.init_predefined(pf.display)
        next_line=self.apply_cmdline_defines(pf)
        # -include files
        if self.st.include_files:
            cmd=PPFile('<command line>',None,''); cmd.is_cmdline=True
            cmd.logical_name='<command line>'
            saved_stack=self.stack; pf.current_line=0
            self.stack=[pf, cmd]
            try:
                ln=next_line
                for inc in self.st.include_files:
                    cmd.current_line=ln
                    if self.writer is not None and self.st.d_mode!=2 and self.st.pp_style!=0:
                        self.writer.marker(ln+1,'<command line>')
                    # The include directive is written in the context of the main file search for quotes:
                    # use a pseudo parent whose display dir matches top file for search, but diagnostics use cmdline.
                    # Temporarily set cmd.display for search dir resolution:
                    search_parent=PPFile(pf.display, pf.fs_path, '')
                    search_parent.logical_name='<command line>'; search_parent.current_line=ln
                    found=self.find_include(inc, True, search_parent, False)
                    if found is None:
                        self.error(f"include file '{inc}' not found", cmd, ln)
                    disp,fs,isys,idx=found
                    incpf=self.read_ppfile(disp,fs,isys,idx)
                    if incpf is None:
                        self.error(f"include file '{inc}' not found", cmd, ln)
                    self.add_dep(incpf)
                    self.st.pp_stats_bytes += incpf.byte_len
                    if incpf.fs_path is not None: self.st.pp_stats_lines += incpf.text.count('\n')
                    if self.writer is not None:
                        self.writer.marker(1,disp,1)
                    # process with stack = [pf, cmd, incpf handled by process_file]
                    self.process_file(incpf, is_top=False)
                    if self.writer is not None:
                        self.writer.finish_line_if_needed()
                        self.writer.marker(ln+1,'<command line>',2)
                    ln+=1
            finally:
                self.stack=saved_stack
        if self.writer is not None and self.st.d_mode!=2 and self.st.pp_style!=0:
            self.writer.marker(1, pf.display, 2)
        pf.current_line=1
        self.process_file(pf, is_top=True)
        if self.writer is not None:
            self.writer.end_top()

class BadExpr(Exception):
    pass

class ExprParser:
    def __init__(self, toks, pp, ppfile, line, canon):
        self.toks=toks; self.i=0; self.pp=pp; self.canon=canon
    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None
    def next(self):
        t=self.peek(); self.i+=1; return t
    def expect(self, txt):
        t=self.next()
        if t is None or t.text!=txt: raise BadExpr('bad')
    def parse(self):
        if not self.toks: raise BadExpr('bad')
        v=self.parse_ternary()
        if self.i!=len(self.toks): raise BadExpr('bad')
        return v
    def parse_ternary(self):
        v=self.parse_or()
        if self.peek() and self.peek().text=='?':
            self.next(); a=self.parse_ternary(); self.expect(':'); b=self.parse_ternary()
            return a if v else b
        return v
    def _binlevel(self, sub, ops):
        v=sub()
        while self.peek() and self.peek().text in ops:
            op=self.next().text
            # For logical operators we still parse RHS (constant folding, no side effects)
            r=sub()
            v=self.apply(op,v,r)
        return v
    def parse_or(self): return self._binlevel(self.parse_and, ('||',))
    def parse_and(self): return self._binlevel(self.parse_bitor, ('&&',))
    def parse_bitor(self): return self._binlevel(self.parse_bitxor, ('|',))
    def parse_bitxor(self): return self._binlevel(self.parse_bitand, ('^',))
    def parse_bitand(self): return self._binlevel(self.parse_eq, ('&',))
    def parse_eq(self): return self._binlevel(self.parse_rel, ('==','!='))
    def parse_rel(self): return self._binlevel(self.parse_shift, ('<','>','<=','>='))
    def parse_shift(self): return self._binlevel(self.parse_add, ('<<','>>'))
    def parse_add(self): return self._binlevel(self.parse_mul, ('+','-'))
    def parse_mul(self): return self._binlevel(self.parse_unary, ('*','/','%'))
    def apply(self,op,a,b):
        av=a[0]; bv=b[0]
        try:
            if op=='||': return (1 if (av or bv) else 0, False)
            if op=='&&': return (1 if (av and bv) else 0, False)
            if op=='|': return (av|bv, a[1] or b[1])
            if op=='^': return (av^bv, a[1] or b[1])
            if op=='&': return (av&bv, a[1] or b[1])
            if op=='==': return (1 if av==bv else 0, False)
            if op=='!=': return (1 if av!=bv else 0, False)
            if op=='<': return (1 if av<bv else 0, False)
            if op=='>': return (1 if av>bv else 0, False)
            if op=='<=': return (1 if av<=bv else 0, False)
            if op=='>=': return (1 if av>=bv else 0, False)
            if op=='<<': return (av<<bv, a[1])
            if op=='>>': return (av>>bv, a[1])
            if op=='+': return (av+bv, a[1] or b[1])
            if op=='-': return (av-bv, a[1] or b[1])
            if op=='*': return (av*bv, a[1] or b[1])
            if op=='/':
                if bv==0: raise BadExpr('bad')
                return (int(av/bv) if (av<0) != (bv<0) and av%bv!=0 else av//bv, a[1] or b[1])
            if op=='%':
                if bv==0: raise BadExpr('bad')
                return (av - int(av/bv)*bv if False else (abs(av)%abs(bv))*(1 if av>=0 else -1), a[1] or b[1])
        except BadExpr:
            raise
        except Exception:
            raise BadExpr('bad')
        raise BadExpr('bad')
    def parse_unary(self):
        t=self.peek()
        if t and t.text in ('+','-','!','~'):
            op=self.next().text; v=self.parse_unary()
            if op=='+': return v
            if op=='-': return (-v[0], v[1])
            if op=='!': return (0 if v[0] else 1, False)
            if op=='~': return (~v[0], v[1])
        return self.parse_primary()
    def parse_primary(self):
        t=self.next()
        if t is None: raise BadExpr('bad')
        if t.text=='(':
            v=self.parse_ternary(); self.expect(')'); return v
        if t.kind=='number':
            try:
                return parse_pp_number(t.text)
            except ValueError as e:
                raise BadExpr(str(e))
        if t.kind=='char':
            return (char_const_value(t.text), False)
        raise BadExpr('bad')
