def tokenize_listfile(text):
    toks=[]; cur=''; inq=False; has=False; i=0
    while i < len(text):
        c=text[i]
        if inq:
            if c=='"': inq=False; i+=1; continue
            if c=='\\' and i+1<len(text) and text[i+1] in ('"','\\'):
                cur+=text[i+1]; i+=2; continue
            cur+=c; i+=1; continue
        if c.isspace():
            if has or cur!='':
                toks.append(cur); cur=''; has=False
            i+=1; continue
        if c=='"':
            inq=True; has=True; i+=1; continue
        cur+=c; has=True; i+=1
    if has or cur!='': toks.append(cur)
    return toks

class ArgStream:
    def __init__(self, args):
        self.args=list(args); self.i=0
    def splice_listfile(self, st, name):
        try:
            with open(name,'r',encoding='utf-8',errors='surrogateescape') as f: text=f.read()
        except Exception:
            st.error(f"listfile '{name}' not found")
        toks=tokenize_listfile(text)
        self.args[self.i:self.i]=toks
    def peek_expand(self, st):
        while self.i < len(self.args) and self.args[self.i].startswith('@') and len(self.args[self.i])>=1:
            tok=self.args[self.i]
            # '@' alone also a listfile with empty name
            self.i+=1
            self.splice_listfile_at(st, tok[1:], self.i)
        return self.args[self.i] if self.i < len(self.args) else None
    def splice_listfile_at(self, st, name, pos):
        try:
            with open(name,'r',encoding='utf-8',errors='surrogateescape') as f: text=f.read()
        except Exception:
            st.error(f"listfile '{name}' not found")
        toks=tokenize_listfile(text)
        self.args[pos:pos]=toks
    def next_expand(self, st):
        t=self.peek_expand(st)
        if t is not None:
            self.i+=1; st.last_token=t; st.parsed_any_token=True
        return t
    def next_raw(self, st):
        if self.i < len(self.args):
            t=self.args[self.i]; self.i+=1; st.last_token=t; st.parsed_any_token=True; return t
        return None
