def cross_exec_m32(argv0, original_args):
    if '/' in argv0:
        path = argv0[:argv0.rfind('/')+1] + 'i386-tcc'
        # reference: "./executable" -> "./i386-tcc"; "/a/b" -> "/a/i386-tcc"
    else:
        path = 'i386-tcc'
    try:
        if '/' in path:
            os.execv(path, [path]+original_args)
        else:
            os.execvp(path, [path]+original_args)
    except Exception:
        err_text(f"tcc: could not run '{path}'\n")
        raise TccExit(1)

def tokenize_listfile(text):
    toks=[]; cur=''; inq=False; has=False; i=0
    while i < len(text):
        c=text[i]
        if inq:
            if c=='"': inq=False; i+=1; continue
            if c=='\\' and i+1<len(text) and text[i+1] in ('"','\\'):
                cur+=text[i+1]; i+=2; continue
            cur+=c; i+=1; continue
        if c.isspace():
            if has or cur!='':
                toks.append(cur); cur=''; has=False
            i+=1; continue
        if c=='"':
            inq=True; has=True; i+=1; continue
        cur+=c; has=True; i+=1
    if has or cur!='': toks.append(cur)
    return toks

class ArgStream:
    def __init__(self, args):
        self.args=list(args); self.i=0
    def splice_listfile(self, st, name):
        try:
            with open(name,'r',encoding='utf-8',errors='surrogateescape') as f: text=f.read()
        except Exception:
            st.error(f"listfile '{name}' not found")
        toks=tokenize_listfile(text)
        self.args[self.i:self.i]=toks
    def peek_expand(self, st):
        while self.i < len(self.args) and self.args[self.i].startswith('@') and len(self.args[self.i])>=1:
            tok=self.args[self.i]
            # '@' alone also a listfile with empty name
            self.i+=1
            self.splice_listfile_at(st, tok[1:], self.i)
        return self.args[self.i] if self.i < len(self.args) else None
    def splice_listfile_at(self, st, name, pos):
        try:
            with open(name,'r',encoding='utf-8',errors='surrogateescape') as f: text=f.read()
        except Exception:
            st.error(f"listfile '{name}' not found")
        toks=tokenize_listfile(text)
        self.args[pos:pos]=toks
    def next_expand(self, st):
        t=self.peek_expand(st)
        if t is not None:
            self.i+=1; st.last_token=t; st.parsed_any_token=True
        return t
    def next_raw(self, st):
        if self.i < len(self.args):
            t=self.args[self.i]; self.i+=1; st.last_token=t; st.parsed_any_token=True; return t
        return None
    def remaining_raw(self):
        return self.args[self.i:]

ACTION_NAMES={'obj':'-c','prep':'-E','run':'-run','reloc':'-r','shared':'-shared'}

def set_action(st, new_type, token_text):
    if st.action_specified:
        if st.output_type=='prep':
            st.e_superseded += 1
        st.warning(f"{token_text}: overriding compiler action already specified")
    else:
        st.first_action=token_text
    if new_type=='prep': st.e_ever=True
    st.output_type=new_type; st.action_specified=True

def parse_W(st, suffix):
    # suffix after -W
    if suffix=='':
        return
    name=suffix; val=True
    if name.startswith('no-'):
        val=False; name=name[3:]
    if name=='all':
        st.warn_all=val
        if val: st.warn_implicit=True; st.warn_discarded=True
        return
    if name=='error':
        st.warn_error=val; return
    if name.startswith('error='):
        w=name[6:]
        if val:
            st.warn_error_specific.add(w)
            # enable the named warning itself
            if w=='write-strings': st.warn_write_strings=True
            if w=='implicit-function-declaration': st.warn_implicit=True
            if w=='discarded-qualifiers': st.warn_discarded=True
            if w=='unsupported': st.warn_unsupported=True
        else:
            st.warn_error_specific.discard(w)
        return
    if name=='write-strings': st.warn_write_strings=val
    elif name=='unsupported': st.warn_unsupported=val
    elif name=='implicit-function-declaration': st.warn_implicit=val
    elif name=='discarded-qualifiers': st.warn_discarded=val
    # unknown warnings ignored

def parse_f(st, suffix):
    name=suffix; val=True
    if name.startswith('no-'):
        val=False; name=name[3:]
    st.flags[name]=val
    if name=='unsigned-char': st.char_unsigned=val
    elif name=='signed-char': st.char_unsigned=not val
    elif name=='leading-underscore': st.leading_underscore=val

def parse_linker_subopts(st, content):
    # content after -Wl, (may be empty)
    if content=='':
        return
    parts=content.split(',')
    i=0
    def take_value(opt):
        nonlocal i
        # value in same token after = or next comma part
        if '=' in opt:
            return opt.split('=',1)[1]
        if i+1 < len(parts):
            i+=1; return parts[i]
        return ''
    while i < len(parts):
        opt=parts[i]
        if opt=='':
            st.error("unsupported linker option ''")
        base=opt.split('=',1)[0]
        if base=='-nostdlib':
            st.wl_nostdlib_paths=True; st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,-nostdlib'))
        elif base in ('-whole-archive','--whole-archive'):
            st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,--whole-archive'))
        elif base in ('-no-whole-archive','--no-whole-archive'):
            st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,--no-whole-archive'))
        elif base in ('-export-all-symbols','-export-dynamic','--export-dynamic'):
            st.rdynamic=True; st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,--export-dynamic'))
        elif base in ('-image-base','-Ttext'):
            v=take_value(opt); st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-Ttext={v}'))
        elif base=='-section-alignment':
            v=take_value(opt)  # ignored on ELF
        elif base=='-rpath':
            v=take_value(opt); st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-rpath={v}'))
        elif base=='-enable-new-dtags':
            st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,--enable-new-dtags'))
        elif base=='-soname':
            v=take_value(opt); st.soname=v
        elif base=='-dynamic-linker':
            v=take_value(opt); st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-dynamic-linker={v}'))
        elif base.startswith('-I') and len(base)>=2 and base not in ('-init',):
            v=opt[2:].lstrip('=') if len(opt)>2 else take_value(opt)
            st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-dynamic-linker={v}'))
        elif base=='-Bsymbolic':
            st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,-Bsymbolic'))
        elif base=='-oformat':
            v=take_value(opt); st.output_format=v
        elif base in ('-init','-fini','-Map'):
            v=take_value(opt)
            if base=='-init': st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-init={v}'))
            elif base=='-fini': st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-fini={v}'))
            # -Map ignored
        elif base=='-as-needed':
            st.items.append(InputItem('linkopt',opt,gcc_arg='-Wl,--as-needed'))
        elif opt=='-O':
            pass
        elif base=='-z':
            v=take_value(opt)
            st.items.append(InputItem('linkopt',opt,gcc_arg=f'-Wl,-z,{v}' if v else '-Wl,-z'))
        else:
            st.error(f"unsupported linker option '{opt}'")
        i+=1

# Options that take an argument, as (prefix, canonical-name)
ARG_OPTS = [
    ('-include','-include'), ('-isystem','-isystem'), ('-soname','-soname'),
    ('-rstdin','-rstdin'), ('-arch','-arch'), ('--param','--param'),
    ('-MF','-MF'), ('-B','-B'), ('-I','-I'), ('-D','-D'), ('-U','-U'),
    ('-L','-L'), ('-l','-l'), ('-o','-o'), ('-x','-x'),
]
EARLY_ONLY = {'-h','-hh','--help','-print-search-dirs','-ar'}
EXACT_FLAGS = {
 '-c':'c','-E':'E','-r':'r','-w':'w','-s':'s','-C':'C','-bench':'bench','-run':'run',
 '-shared':'shared','-static':'static','-nostdinc':'nostdinc','-nostdlib':'nostdlib',
 '-rdynamic':'rdynamic','-pthread':'pthread','-pedantic':'ignore','-pipe':'ignore',
 '-traditional':'ignore','-M':'M','-MM':'MM',
}

def process_option(st, stream, tok, original_args, argv0, in_wp=False):
    """Process one option/file token already consumed from stream.
    Returns 'break' if run-mode parsing should stop, else None."""
    # -- handling
    if tok=='--':
        if st.output_type=='run' and st.action_specified:
            st.run_argv=['--']+stream.remaining_raw()
            st.run_terminated=True
            return 'break'
        return None
    # file (including '-')
    if not tok.startswith('-') or tok=='-':
        st.still_early=False
        item=InputItem('file', tok, x_type=st.x_current)
        st.items.append(item)
        if st.output_type=='run':
            st.run_argv=[tok]+stream.remaining_raw()
            st.run_terminated=True
            return 'break'
        return None
    # -m32 deferral happens as soon as it is parsed as an option
    if tok=='-m32':
        cross_exec_m32(argv0, original_args)
    # early determination
    def mark_early():
        pass
    is_early_token = False
    if tok=='-m64' or tok.startswith('-B') or (tok.startswith('-v') and not tok.startswith('--')) or tok=='--version' or tok=='-dumpversion':
        is_early_token=True
    if tok in EARLY_ONLY:
        if not st.still_early:
            st.error(f"cannot parse {tok} here")
        # handle below
    elif not is_early_token:
        # -dumpversion allowed anywhere (handled as early-token above)
        st.still_early=False

    # ---- dispatch ----
    # version family: any token starting -v (single dash), plus --version/-version
    if tok=='--version' or (tok.startswith('-v') and not tok.startswith('--')):
        cnt=0
        if tok=='--version': cnt=1
        else:
            j=1
            while j < len(tok) and tok[j]=='v': cnt+=1; j+=1
            if cnt==0: cnt=1
        st.verbose += cnt
        st.version_pending=True
        return None
    if tok in ('-h','--help'):
        out_text(HELP_TEXT); raise TccExit(0)
    if tok=='-hh':
        out_text(HELP2_TEXT); raise TccExit(0)
    if tok=='-dumpversion':
        out_text(VERSION+'\n'); raise TccExit(0)
    if tok=='-print-search-dirs':
        st.flush_version(); print_search_dirs(st); raise TccExit(0)
    if tok=='-ar':
        st.flush_version()
        rest=stream.remaining_raw()
        # consume rest (no @ expansion of operands? reference expands listfiles before ar in early args; operands from original argv are raw)
        code=do_ar(st, rest)
        raise TccExit(code)
    if tok=='-m64':
        return None
    # -run with attached file
    if tok.startswith('-run') and tok!='-run':
        set_action(st,'run','-run')
        attached=tok[4:]
        st.items.append(InputItem('file',attached,x_type=st.x_current,attached_run=True))
        return None
    # -Wl, and -Wp, before generic -W
    if tok.startswith('-Wl,'):
        parse_linker_subopts(st, tok[4:]); return None
    if tok.startswith('-Wp,'):
        sub=tok[4:]
        if sub=='':
            return None
        subtoks=sub.split(',')
        substream=ArgStream(subtoks)
        while True:
            t=substream.next_raw(st)
            if t is None: break
            if t=='' : continue
            r=process_option(st, substream, t, original_args, argv0, in_wp=True)
            if r=='break': break
        return None
    # argument options (longest prefixes first; -std special handled below before -s exact etc.)
    if tok.startswith('-std'):
        suffix=tok[4:]
        st.std_raw=suffix
        st.std_is_c11 = suffix in ('=c11','=gnu11')
        return None
    # -MD / -MMD with arbitrary trailing suffix
    if tok.startswith('-MMD'):
        st.gen_deps_file=True; st.deps_ignore_system=True; st.deps_seen=True; return None
    if tok.startswith('-MD'):
        st.gen_deps_file=True; st.deps_seen=True; return None
    for prefix, canon in ARG_OPTS:
        if tok==prefix or tok.startswith(prefix):
            # ensure this is really this option: for single-letter prefixes any suffix is the arg.
            # for long prefixes, tok must be prefix or start with prefix (suffix is arg)
            if tok==prefix:
                val=stream.next_raw(st)
                if val is None:
                    st.error(f"argument to '{canon}' is missing")
            else:
                val=tok[len(prefix):]
            handle_arg_option(st, canon, val, tok)
            return None
    # exact flags
    if tok in EXACT_FLAGS:
        kind=EXACT_FLAGS[tok]
        if kind=='c': set_action(st,'obj','-c')
        elif kind=='E': set_action(st,'prep','-E')
        elif kind=='run': set_action(st,'run','-run')
        elif kind=='r': set_action(st,'reloc','-r')
        elif kind=='shared': set_action(st,'shared','-shared')
        elif kind=='w': st.warn_none=True
        elif kind=='bench': st.bench=True
        elif kind=='nostdinc': st.nostdinc=True
        elif kind=='nostdlib': st.nostdlib=True
        elif kind=='static': st.static_link=True
        elif kind=='rdynamic': st.rdynamic=True
        elif kind=='pthread':
            st.pthread=True
            st.cmd_defines.append(('D','_REENTRANT=1'))
            st.gcc_pp_args.append('-D_REENTRANT=1')
            st.items.append(InputItem('lib','pthread'))
        elif kind=='M': st.gen_deps_only=True; st.deps_seen=True
        elif kind=='MM': st.gen_deps_only=True; st.deps_ignore_system=True; st.deps_seen=True
        elif kind in ('s','C','ignore'): pass
        return None
    # families
    if tok.startswith('-bt'):
        st.backtrace=True; st.debug=True
        suffix=tok[3:]
        try: st.bt_value=int(suffix) if suffix and suffix.lstrip('-').isdigit() else 0
        except Exception: st.bt_value=0
        return None
    if tok=='-b':
        st.bounds=True; st.debug=True; return None
    if tok.startswith('-W'):
        parse_W(st, tok[2:]); return None
    if tok.startswith('-f'):
        parse_f(st, tok[2:]); return None
    if tok.startswith('-O'):
        suffix=tok[2:]
        st.optimize = not suffix.startswith('0')
        return None
    if tok.startswith('-g'):
        st.debug=True
        if tok.startswith('-gdwarf'):
            rest=tok[7:]
            m=re.search(r'(\d+)', rest)
            st.gdwarf=int(m.group(1)) if m else 4
        return None
    if tok.startswith('-d'):
        suffix=tok[2:]
        if suffix:
            c=suffix[0]
            if c=='D': st.d_mode=1
            elif c=='M': st.d_mode=2
            elif c=='t': st.dt=True
        return None
    if tok.startswith('-P'):
        suffix=tok[2:]
        try: v=int(suffix) if suffix else 0
        except Exception: v=0
        if v==1: st.pp_style=1
        elif v>=2: st.pp_style=2
        else: st.pp_style=0
        return None
    if tok.startswith('-m'):
        name=tok[2:]
        val=True
        if name.startswith('no-'): val=False; name=name[3:]
        st.mflags[name]=val
        return None
    st.error(f"invalid option -- '{tok}'")
    return None

def handle_arg_option(st, canon, val, tok):
    if canon=='-o':
        if st.outfile_seen>=1:
            st.warning('multiple -o option')
        st.outfile_seen+=1; st.outfile=val
    elif canon=='-I':
        st.include_dirs.append(val); st.gcc_pp_args.append('-I'+val)
    elif canon=='-isystem':
        st.system_include_dirs.append(val); st.gcc_pp_args.append('-isystem'); st.gcc_pp_args.append(val)
    elif canon=='-D':
        st.cmd_defines.append(('D',val)); st.gcc_pp_args.append('-D'+val)
    elif canon=='-U':
        st.cmd_defines.append(('U',val)); st.gcc_pp_args.append('-U'+val)
    elif canon=='-L':
        st.lib_dirs.append(val)
    elif canon=='-l':
        st.items.append(InputItem('lib',val))
    elif canon=='-B':
        st.tccdir=val
    elif canon=='-include':
        st.include_files.append(val); st.gcc_pp_args.append('-include'); st.gcc_pp_args.append(val)
    elif canon=='-soname':
        st.soname=val
    elif canon=='-MF':
        st.mf_file=val
    elif canon=='-rstdin':
        st.rstdin=val
    elif canon=='-x':
        if val in ('c','a','b'):
            st.x_current=val
        elif val=='n':
            st.x_current=None
        else:
            st.warning(f"unsupported language '{val}'")
            st.x_current=None
    elif canon in ('-arch','--param'):
        pass

def parse_args(st, args, argv0):
    stream=ArgStream(args)
    original_args=list(args)
    while True:
        tok=stream.next_expand(st)
        if tok is None: break
        r=process_option(st, stream, tok, original_args, argv0)
        if r=='break': break
    # no-terminator run argv quirk: last token
    if st.output_type=='run' and not st.run_terminated:
        if st.last_token:
            st.run_argv=[st.last_token]
    return st
