def default_object_name(name):
    if name=='-': return 'a.out'
    base=os.path.basename(name)
    if '.' in base:
        return base.rsplit('.',1)[0]+'.o'
    return 'a.out'

def dep_file_name_for(target, mf):
    if mf is not None: return mf
    d=os.path.dirname(target); base=os.path.basename(target)
    if '.' in base:
        nb=base.rsplit('.',1)[0]+'.d'
    else:
        nb=base+'.d'
    return os.path.join(d,nb) if d else nb

def format_deps(target, deps, ignore_system):
    ds=[]
    for disp,isys in deps:
        if ignore_system and isys: continue
        ds.append(disp)
    if not ds:
        return f"{target}:\n"
    s=f"{target}: \\\n"
    for i,d in enumerate(ds):
        dd=d.replace(' ','\\ ')
        s += f"  {dd}" + (" \\\n" if i < len(ds)-1 else "\n")
    return s

def gcc_deps_for_file(st, item, ftype):
    """Use host compiler -M to obtain deps; returns list of (disp,is_system) or None."""
    args=gcc_base_args(st)
