    else:
        if ftype=='c' and item.x_type=='c': args += ['-x','c']
        args.append(item.name)
    p=subprocess.run(args, input=inp, capture_output=True)
    if p.returncode!=0: return None
    txt=p.stdout.decode('utf-8','surrogateescape')
    # join continuation lines
    txt=txt.replace('\\\n',' ')
    if ':' not in txt: return None
    rest=txt.split(':',1)[1]
