        cur+=c; i+=1
    if cur: toks.append(cur)
    sys_prefixes=('/usr/include','/usr/local/include','/usr/lib/gcc', st.tccdir+'/include')
    sys_dirs=set(os.path.realpath(d) if os.path.exists(d) else d for d in st.system_include_dirs)
