def verbose_file_line(st, name, exists=True):
    if st.verbose<=0: return
    if not exists:
        if st.verbose==1: out_text(f"-> {name}\n")
        elif st.verbose==3: out_text(f"nf {name}\n")
        return
    if 1 <= st.verbose <= 3:
        out_text(f"-> {name}\n")

def verbose_output_line(st, name):
    if st.verbose>0:
        out_text(f"<- {name}\n")

def check_file_exists(st, item):
    if item.name=='-': return True
    if os.path.exists(item.name): return True
    verbose_file_line(st, item.name, exists=False)
    st.error(f"file '{item.name}' not found")
