    for ident in st.pp_stats_idents:
        if ident not in BASE_IDENT_SET: extra+=1
    # For GCC-compiled files we did not run our PP; estimate idents from source identifiers happens in compile path via reading files below.
    idents=base_idents+extra
    lines=st.pp_stats_lines; byts=st.pp_stats_bytes
    elapsed=max(time.time()-st.bench_start, 0.001)
    # Reference quantizes to ms with a floor that usually prints 0.001 for tiny inputs.
    shown_t = 0.001 if elapsed < 0.0015 else round(elapsed,3)
    lps = int(lines/shown_t) if shown_t>0 else 0
    mbps = (byts/1048576.0)/shown_t if shown_t>0 else 0
    text=drw=dro=bss=0
    if not is_pp_only:
        objs=objects if objects is not None else st.bench_objects
        text,drw,dro,bss=object_sections_totals([o for o in objs if o and os.path.exists(o)])
    err_text(f"# {idents} idents, {lines} lines, {byts} bytes\n")
    err_text(f"# {shown_t:.3f} s, {lps} lines/s, {mbps:.1f} MB/s\n")
    err_text(f"# text {text}, data.rw {drw}, data.ro {dro}, bss {bss} bytes\n")

def collect_source_stats(st, item):
    # For bench in GCC compile mode: count bytes/lines/idents by a lightweight scan.
    try:
        if item.name=='-':
            data=st.stdin_data or b''; lines=0
        else:
            with open(item.name,'rb') as f: data=f.read()
            lines=data.count(b'\n')
        st.pp_stats_bytes += len(data); st.pp_stats_lines += lines
        txt=data.decode('utf-8','ignore')
        for m in re.finditer(r'[A-Za-z_$][A-Za-z0-9_$]*', txt):
            st.pp_stats_idents.add(m.group(0))
    except Exception:
        pass

def run_preprocess(st):
    # open output
    outfp=None; out_is_stdout=False
    if st.outfile is None or st.outfile=='-':
        outfp=sys.stdout.buffer; out_is_stdout=True
    # leading newlines from superseded -E actions go to stdout
    if st.e_superseded:
        out_text('\n'*st.e_superseded)
    writer=None
    created=False
    # process each file item in order, interleaving library items
    any_processed=False
    for item in st.items:
        if item.kind=='linkopt': continue
        if item.kind=='lib':
            # libraries are looked up ( only explicit dirs in this mode)
            if find_library(st, item.name, 'prep') is None:
                if writer is not None and st.output_type=='prep':
                    pass
                st.error(f"library '{item.name}' not found")
            continue
        # file item
        if not created:
            if not out_is_stdout:
                try:
                    outfp=open(st.outfile,'wb')
                except OSError:
                    # reference prints a newline to stdout in this situation
                    out_text('\n')
                    st.error(f"could not write '{st.outfile}'")
            created=True
            writer=PPWriter(st, outfp, enabled=True)
            # The writer for -E to a file should capture diagnostic-newlines in the file; default is same fp.
            if st.bench:
                writer.suppress_normal=True
        # existence / type
        if item.name!='-' and not os.path.exists(item.name):
            verbose_file_line(st, item.name, exists=False)
            if writer is not None: writer.diagnostic_newline()
            st.error(f"file '{item.name}' not found")
        ftype=detect_file_type(st,item)
        if ftype=='unknown':
            st.error(f"{item.name}: unrecognized file type")
        verbose_file_line(st, item.name, exists=True)
        if ftype in ('elf','archive'):
            continue
        if ftype=='asm':
            # TCC preprocesses asm files too (at PP-token level). Our PP can handle token text generically.
            pass
        deps=[]
        pp=Preprocessor(st, writer, deps)
        try:
            pp.process_top(item.name, None if item.name=='-' else item.name)
        except PPError:
            if outfp and not out_is_stdout: outfp.close()
            raise TccExit(1)
        any_processed=True
    if outfp and not out_is_stdout:
        outfp.close()
        if any_processed or created:
            verbose_output_line(st, st.outfile)
    bench_print(st)
    return 0

