def prepare_link_items(st, mode):
    """Process items in order compiling sources to temp objects.
    Returns (gcc_link_args, temp_objects, all_deps, dup_warnings_made) or raises/None on error via returncode path.
    On error returns None after printing diagnostics (caller returns 1)."""
    tmpdir=tempfile.mkdtemp(prefix='tcclink-')
    link_args=[]; temp_objs=[]; all_deps=[]
    defined={}  # sym -> (item, kind)
    dup_src_error=False
    allow_multiple=False
    for_shared = (mode=='shared')
    for item in st.items:
        if item.kind=='linkopt':
            link_args.append(item.gcc_arg); continue
        if item.kind=='lib':
            found=find_library(st,item.name, mode if mode in ('exe','shared','run') else 'reloc')
            if found is None:
                st.error(f"library '{item.name}' not found")
            if st.verbose>=2 and st.verbose<=3 and mode in ('exe','shared','run'):
                out_text(f"-> {found}\n")
            link_args.append('-l'+item.name)
            # symbols from a static archive could define; ignore for duplicate checks
            continue
        # file
        check_file_exists(st,item)
        ftype=detect_file_type(st,item)
        if ftype=='unknown':
            st.error(f"{item.name}: unrecognized file type")
        verbose_file_line(st,item.name,True)
        collect_source_stats(st,item)
        obj_for_symbols=None
        if ftype in ('c','asm'):
            tmpobj=os.path.join(tmpdir,f'f{len(temp_objs)}.o')
            if not compile_one_gcc(st,item,ftype,tmpobj,for_shared=for_shared):
                shutil.rmtree(tmpdir,ignore_errors=True); return None
            temp_objs.append(tmpobj); link_args.append(tmpobj); obj_for_symbols=tmpobj
            if st.gen_deps_file:
                # collect deps for final dep file (single)
                gd=gcc_deps_for_file(st,item,ftype)
                if gd:
                    for d in gd:
                        if d not in all_deps: all_deps.append(d)
                else:
                    if (item.name,False) not in all_deps: all_deps.append((item.name,False))
        elif ftype=='elf':
            link_args.append(item.name); obj_for_symbols=item.name
        elif ftype=='archive':
            if mode=='reloc':
                link_args += ['-Wl,--whole-archive', item.name, '-Wl,--no-whole-archive']
            else:
                link_args.append(item.name)
            obj_for_symbols=item.name
        # duplicate symbol checks
        if obj_for_symbols:
            syms=file_defined_symbols(obj_for_symbols)
            for sym in sorted(syms):
                if sym in defined:
                    if ftype in ('c','asm'):
                        # Source defining a symbol twice across units is an error in TCC.
                        # But only if this same source didn't already get a GCC redefinition error (handled).
                        # Location: end-of-file line
                        if item.name=='-':
                            lc=source_line_count(st,item,ftype) or 1
                        else:
                            try:
                                txt=open(item.name,errors='surrogateescape').read(); lc=txt.count('\n')+1
                            except Exception: lc=1
                        err_text(f"{item.name}:{lc}: error: '{sym}' defined twice\n")
                        shutil.rmtree(tmpdir,ignore_errors=True); raise TccExit(1)
                    else:
                        err_text(f"{item.name}: error: '{sym}' defined twice\n")
                        allow_multiple=True
                else:
                    defined[sym]=(item,ftype)
    return (link_args, temp_objs, tmpdir, all_deps, allow_multiple)

def link_and_finish(st, prepared, mode, final_out):
    link_args, temp_objs, tmpdir, all_deps, allow_multiple = prepared
    tmpout=os.path.join(tmpdir,'a.out.bin')
    suc, undef, errt = gcc_link(st, link_args, tmpout, mode, allow_multiple=allow_multiple)
    if not suc:
        if undef:
            for s in undef:
                err_text(f"tcc: error: undefined symbol '{s}'\n")
            shutil.rmtree(tmpdir,ignore_errors=True); return 1
        # other link errors: strip ld prefix lines of interest
        emitted=False
        for ln in errt.splitlines():
            if 'multiple definition of' in ln:
                m=re.search(r"multiple definition of ['`]([^'`]+)['`]", ln)
                if m: err_text(f"tcc: error: '{m.group(1)}' defined twice\n"); emitted=True
        if not emitted:
            # entry symbol with nostdlib may still be success in gcc; here generic
            lines=[l for l in errt.splitlines() if l.strip() and 'collect2' not in l]
            msg=lines[0] if lines else 'link failed'
            msg=re.sub(r'^(?:/usr/bin/ld|ld):\s*','',msg)
            err_text(f"tcc: error: {msg}\n")
        shutil.rmtree(tmpdir,ignore_errors=True); return 1
    # success: nostdlib _start check for exe
    if mode=='exe' and st.nostdlib:
        # check symbols of the produced executable
        defs=set()
        try:
            with open(tmpout,'rb') as f: data=f.read()
            d,_u,_s=elf_symbols(data); defs=d
            # also scan input objects
            for a in link_args:
                if isinstance(a,str) and os.path.isfile(a):
                    defs |= file_defined_symbols(a)
        except Exception:
            pass
        if '_start' not in defs:
            # reference creates an empty output file here
            try:
                with open(final_out,'wb') as f: pass
            except Exception:
                pass
            err_text("tcc: error: _start not defined\n")
            shutil.rmtree(tmpdir,ignore_errors=True); return 1
    # output format binary
    if st.output_format=='binary' and mode in ('exe','shared'):
        binout=os.path.join(tmpdir,'out.binary')
        oc=shutil.which('objcopy')
        if oc:
            subprocess.run([oc,'-O','binary',tmpout,binout],capture_output=True)
            if os.path.exists(binout): tmpout=binout
    if os.path.isdir(final_out):
        output_is_directory_error(st,final_out)
    try:
        shutil.copyfile(tmpout, final_out)
        if mode in ('exe','shared'):
            os.chmod(final_out, 0o755)
    except OSError as e:
        st.error(f"could not write '{final_out}: {e.strerror or e}'")
    verbose_output_line(st, final_out)
    if st.gen_deps_file:
        write_dep_file(st, final_out, all_deps)
    bench_objs=temp_objs[:]
    shutil.rmtree(tmpdir,ignore_errors=True)
    bench_print(st, bench_objs if bench_objs else [final_out])
    return 0

def run_link_mode(st, mode):
    final_out = st.outfile if st.outfile is not None else 'a.out'
    if st.verbose>=2 and st.verbose<=3 and mode=='exe' and not st.nostdlib:
        out_text("-> /usr/lib/x86_64-linux-gnu/crt1.o\n")
        out_text("-> /usr/lib/x86_64-linux-gnu/crti.o\n")
    try:
        prepared=prepare_link_items(st, mode)
    except TccExit:
        raise
    if prepared is None:
        return 1
    link_args, temp_objs, tmpdir, all_deps, allow_multiple = prepared
    # verbose standard libraries trace (approximate)
    if st.verbose>=2 and st.verbose<=3 and mode in ('exe','shared') and not st.nostdlib:
