def discover_dt_tests(st, items):
    """For -run -dt: use our PP in E-like passes over the (first) C sources to
    obtain the ordered list of selected test names per pass.
    Simplified: run PP passes on each file and collect selected markers.
    Returns list of test names (one per run pass)."""
    # Save state affected
    selected=[]
    # We simulate passes with test_wanted=1.. ; each pass record the name chosen on the first matching defined() in any file.
    # Our PP already implements the counter across a single top file. For multiple files, tests in tcctest are in one file, which this covers.
    file_items=[it for it in items if it.kind=='file' and detect_file_type(st,it)=='c']
    if not file_items: return selected
    wanted=1
    # Use the last file item as the test file if multiple? Reference compiles all files each pass; counters continue across files in one state, but our PP resets per top. Use first file for discovery.
    it=file_items[-1]
    for _ in range(200):
        deps=[]; writer=PPWriter(st,None,enabled=False); writer.suppress_normal=True
        pp=Preprocessor(st,writer,deps); pp.quiet=True
        pp.test_wanted=wanted; pp.test_counter=0; pp.test_selected=False
        chosen=[None]
        orig_writer_marker=writer.write_test_marker
        def mark(name, line=None, _chosen=chosen):
            _chosen[0]=name
        writer.write_test_marker=mark
        saved_used=st.stdin_used
        if it.name=='-': st.stdin_used=False
        try:
            pp._process_top_once(pp._make_top_pf(it.name, None if it.name=='-' else it.name))
        except Exception:
            pass
        finally:
            st.stdin_used=saved_used
        if pp.test_counter >= wanted:
            if chosen[0]: selected.append(chosen[0])
            wanted+=1
            continue
        break
    return selected

def run_run_mode(st):
    # dt mode
    if st.dt:
        tests=discover_dt_tests(st, st.items)
        if not tests:
            return 0
        overall=0
        first=True
        for tname in tests:
            if not first:
                out_text('\n')
            first=False
            out_text(f"[{tname}]\n"); sys.stdout.buffer.flush()
            # compile with this test macro defined (empty)
            saved_cmd=list(st.cmd_defines); saved_gcc=list(st.gcc_pp_args)
            st.cmd_defines.append(('D',tname)); st.gcc_pp_args.append('-D'+tname)
            code=execute_compiled(st, suppress_bench=True)
            st.cmd_defines=saved_cmd; st.gcc_pp_args=saved_gcc
            if isinstance(code, tuple) and code and code[0]=='signal':
                # propagate crash
                import signal as _sig
                os.kill(os.getpid(), code[1]); return 128+code[1]
            out_text(f"[returns {code}]\n"); sys.stdout.buffer.flush()
        return 0
    code=execute_compiled(st)
    if isinstance(code, tuple) and code and code[0]=='signal':
        import signal as _sig
        sig=code[1]
        # reset to default and re-raise so parent sees death by signal
        try:
            _sig.signal(sig, _sig.SIG_DFL)
        except Exception: pass
        os.kill(os.getpid(), sig)
        return 128+sig
    return code

def execute_compiled(st, suppress_bench=False):
    """Compile items to a temp executable and run it with st.run_argv. Returns exit code or ('signal', n)."""
    # rstdin handling: check file now (after compile in reference; error before execution)
    prepared=prepare_link_items(st, 'run')
    if prepared is None:
        return 1
    link_args, temp_objs, tmpdir, all_deps, allow_multiple = prepared
    tmpout=os.path.join(tmpdir,'prog')
    suc, undef, errt=gcc_link(st, link_args, tmpout, 'exe', allow_multiple=allow_multiple)
    if not suc:
        if undef:
            for s in undef: err_text(f"tcc: error: undefined symbol '{s}'\n")
        else:
            lines=[l for l in errt.splitlines() if l.strip()]
            err_text(f"tcc: error: {lines[0] if lines else 'link failed'}\n")
        shutil.rmtree(tmpdir,ignore_errors=True); return 1
    os.chmod(tmpout,0o755)
    # stdin for child
    stdin_obj=None; close_stdin=False
    if st.rstdin is not None:
        try:
            stdin_obj=open(st.rstdin,'rb'); close_stdin=True
        except Exception:
            err_text(f"tcc: error: failed to reopen stdin from '{st.rstdin}'\n")
            shutil.rmtree(tmpdir,ignore_errors=True); return 1
    argv=[tmpout]+list(st.run_argv[1:]) if st.run_argv else [tmpout]
    # Reference passes argv[0] = run_argv[0] text, not the temp path.
    display_argv=list(st.run_argv) if st.run_argv else [tmpout]
    try:
        # Use subprocess with executable override so argv0 is display name
        p=subprocess.run(display_argv, executable=tmpout, stdin=stdin_obj)
        rc=p.returncode
    except Exception as e:
        rc=1
    finally:
        if close_stdin: stdin_obj.close()
        shutil.rmtree(tmpdir,ignore_errors=True)
    if rc is not None and rc<0:
        return ('signal', -rc)
    return rc if rc is not None else 1

def main(argv):
    st=State()
    argv0=argv[0] if argv else 'tcc'
    args=argv[1:]
    try:
        parse_args(st, args, argv0)
        # "no arguments at all (after removing early-only options)" -> help / version
        has_files=any(it.kind in ('file','lib') for it in st.items)
        if not has_files and st.still_early:
            if st.verbose>0:
                st.flush_version()
                if st.verbose==2:
                    print_search_dirs(st)
                return 0
            out_text(HELP_TEXT); return 0
        st.flush_version()
        if not has_files:
            # library-only input is handled as has_files above (lib counts)
            if st.e_ever:
                # empty preprocessed output consists of a newline per superseded -E plus one
                out_text('\n'*(st.e_superseded+1))
            st.error('no input files')
        # leading stdout newlines for superseded -E in modes other than prep are emitted by run_preprocess for prep;
        # for other modes emit now (they appear before any other stdout).
