    """Compile items to a temp executable and run it with st.run_argv. Returns exit code or ('signal', n)."""
    # rstdin handling: check file now (after compile in reference; error before execution)
    prepared=prepare_link_items(st, 'run')
    if prepared is None:
        return 1
    link_args, temp_objs, tmpdir, all_deps, allow_multiple = prepared
    tmpout=os.path.join(tmpdir,'prog')
    suc, undef, errt=gcc_link(st, link_args, tmpout, 'exe', allow_multiple=allow_multiple)
    if not suc:
        if undef:
            for s in undef: err_text(f"tcc: error: undefined symbol '{s}'\n")
        else:
            lines=[l for l in errt.splitlines() if l.strip()]
            err_text(f"tcc: error: {lines[0] if lines else 'link failed'}\n")
        shutil.rmtree(tmpdir,ignore_errors=True); return 1
    os.chmod(tmpout,0o755)
    # stdin for child
    stdin_obj=None; close_stdin=False
    if st.rstdin is not None:
        try:
